def cp_pool_link(info: dict) -> str:
    """CheesePad pool link (with affiliate ref)."""
    url = info.get("url", "") or ""
    if not url and info.get("address"):
        url = (f"https://www.cheesepad.ai/sale/"
               f"{(info.get('chain') or 'bsc').lower()}/{info['address']}")

    return affiliate_link(url)


def _cp_sale_type(details, info):
    """English sale type: 'Whitelist' or 'Public'."""
    raw = " ".join(str(details.get(k, "")) for k in
                   ("sale_type", "whitelist", "status", "name")).lower()
    if any(w in raw for w in ("whitelist", "wl only", "wl-only", "private")):
        return "Whitelist"
    wl = details.get("whitelist")
    if wl in (True, "true", "True", 1, "1"):
        return "Whitelist"
    return "Public"


def _cp_is_fairlaunch(details, info) -> bool:
    raw = " ".join(str(x) for x in (info.get("url", ""), info.get("sale_type_hint", ""),
                                    details.get("sale_type", ""), details.get("status", ""))).lower()
    return ("fair" in raw) or (not _ps_num(details.get("hard_cap")))


def build_cheesepad_post(channel, msg_id, info, details, pid):
    """Owner-approved CheesePad template. Returns (html_text, ordered_emoji_ids).
    🔮 order: chain, chain, info, cap, buy, time, details, cheesepad, kol"""
    chain = (info.get("chain") or "").upper()
    name  = (_lp_fmt_val(details.get("name")) or _lp_fmt_val(details.get("symbol"))
             or "New Project")
    soft  = _ps_amount(details.get("soft_cap"), chain)
    hard  = _ps_amount(details.get("hard_cap"), chain)
    mnb   = _ps_amount(details.get("min_buy"), chain)
    mxb   = _ps_amount(details.get("max_buy"), chain)
    raised = _ps_amount(details.get("raised"), chain)
    live   = _ps_is_live(details)
    start  = _ps_time(details.get("start_time"))
    end    = _ps_time(details.get("end_time"))
    if details.get("currency"):   # data really came from the CheesePad API -> a 0/empty value means "none"
        mnb  = mnb  or "No Min"
        mxb  = mxb  or "No Max"
        soft = soft or "No Soft Cap"
        hard = hard or "No Hard Cap"

    pool_link = cp_pool_link(info)
    det_link  = f"{BOT_LINK}?start=cp_{pid}"
    ch_link   = f"https://t.me/{channel}/{msg_id}" if channel and msg_id else TG_CHANNEL_LINK
    kind      = "Fairlaunch" if _cp_is_fairlaunch(details, info) else "Presale"

    custom_tpl = cfg_get("cp_channel_template", "")
    if custom_tpl:
        rendered = _render_template(custom_tpl, {
            "name": html.escape(name), "caller": html.escape(channel), "chain": chain,
            "sale_type": _cp_sale_type(details, info),
            "soft_cap": soft or "N/A", "hard_cap": hard or "No Hard Cap",
            "min_buy": mnb or "No Min Buy", "max_buy": mxb or "No Max Buy",
            "raised": raised if (live and raised) else "",
            "starts": (kind + " is already live") if live else (start or "N/A"),
            "ends": end or "N/A", "cheesepad_link": pool_link, "details_link": det_link,
            "kol_link": ch_link,
        })
        if rendered is not None:
            ce = _cp_chain_emoji(chain)
            emoji_ids = [ce, ce, CP_EMOJI["eye"], CP_EMOJI["target"], CP_EMOJI["crystal"],
                         CP_EMOJI["fire"], CP_EMOJI["details"], CP_EMOJI["cheesepad"],
                         CP_EMOJI["kol"]]
            return rendered, emoji_ids

    # ── DEFAULT TEMPLATE (owner 2026-10-02) ──────────────────────────────────
    # Same layout as PinkSale, CheesePad emojis. Every premium emoji is embedded
    # by explicit ID via <tg-emoji>, so nothing depends on 🔮 marker order.
    def _e(eid, fb):
        return f'<tg-emoji emoji-id="{eid}">{fb}</tg-emoji>'

    LBL    = _e(CP_LABEL_EMOJI_ID, "🧀")
    VAL    = _e(CP_VALUE_EMOJI_ID, "🧀")
    banner = "".join(_e(i, "🧀") for i in CP_BANNER_EMOJI_IDS)

    sym = str(_lp_fmt_val(details.get("symbol")) or "").strip().lstrip("$")
    token_plain = f"${sym}" if sym else str(name)
    chain_plain = _PS_CHAIN_DISPLAY.get(chain, chain) if chain else "N/A"
    sale_plain  = "Whitelist sale" if _cp_sale_type(details, info) == "Whitelist" else "Public sale"
    handle      = html.escape(_display_handle(channel))

    t  = banner + "\n\n"
    t += (f"<b>@{handle} has posted a CheesePad project. "
          f"Click Details to view the project information.</b>\n\n")

    t += f"{_e(CP_HDR_TOKEN_ID, '🧀')} <b>TOKEN INFO</b>\n"
    t += ("<blockquote>" + _ps_grid(LBL, VAL, [
        ("Sale Type", sale_plain),
        ("Chain", chain_plain),
        ("TOKEN", token_plain),
    ]) + "</blockquote>\n\n")

    t += f"{_e(CP_HDR_SALE_ID, '🧀')} <b>SALE Details</b>\n"
    t += ("<blockquote>" + _ps_grid(LBL, VAL, [
        ("Min Buy", mnb or _lp_na(details, "min_buy", "No Min")),
        ("Max Buy", mxb or _lp_na(details, "max_buy", "No Max")),
        ("Softcap", soft or _lp_na(details, "soft_cap", "No Soft Cap")),
        ("Hardcap", hard or _lp_na(details, "hard_cap", "No Hard Cap")),
    ]) + "</blockquote>\n\n")

    t += f"{_e(CP_HDR_TIME_ID, '🧀')} <b>TIME Details</b>\n"
    t += (f"<blockquote>{VAL} <b>Starts:</b> {(kind + ' is already live') if live else (start or 'N/A')}\n"
          f"{VAL} <b>Ends:</b> {end or 'N/A'}</blockquote>\n\n")

    t += (f'{_e(CP_LINK_DETAILS_ID, "🧀")}<a href="{det_link}">Details</a>  '
          f'{_e(CP_LINK_CHEESEPAD_ID, "🧀")}<a href="{pool_link}">CheesePad</a>  '
          f'{_e(CP_LINK_KOL_ID, "🧀")}<a href="{ch_link}">KOL</a>')

    # Explicit IDs win; the send helpers only need a NON-empty id list.
    return t, [CP_EMOJI["cheesepad"]]


def _cp_pe(eid, fallback):
    return f'<tg-emoji emoji-id="{eid}">{fallback}</tg-emoji>'


def build_cp_details_text(pid, rec, premium=True):
    """Full CheesePad breakdown shown when someone taps Details (inside the bot)."""
    d       = rec.get("details", {}) or {}
    chain   = (rec.get("chain") or "").upper()
    channel = rec.get("channel", "")
    msg_id  = rec.get("msg_id", "")
    name    = d.get("name") or d.get("symbol") or "New Project"
    info    = {"chain": chain, "url": rec.get("url", ""), "address": rec.get("address", ""),
               "sale_type_hint": ""}
    live    = _ps_is_live(d)
    kind    = "Fairlaunch" if _cp_is_fairlaunch(d, info) else "Presale"
    pool    = cp_pool_link(info)

    # Sirf CheesePad ki apni emojis — koi PinkSale emoji yahan nahi aati.
    _ALIAS = {"dot": "details", "chart": "cheesepad", "zap": "details",
              "scan": "details", "ca": "details", "warn": "cheesepad"}

    def em(key, fb):
        key = _ALIAS.get(key, key)
        return _cp_pe(CP_EMOJI[key], fb) if premium else fb

    def row(key, fb, label, val):
        return f"{em(key, fb)} <b>{label}:</b> {val}\n" if val else ""

    _cem = _cp_pe(_cp_chain_emoji(chain), "🔮") if premium else "🔮"

    custom_tpl = cfg_get("cp_details_template", "")
    if custom_tpl:
        _tok_early = d.get("token") or ""
        rendered = _render_template(custom_tpl, {
            "name": html.escape(str(name)), "caller": html.escape(channel), "chain": chain,
            "sale_type": _cp_sale_type(d, info), "token": d.get("symbol") or "",
            "supply": _ps_supply(d.get("supply"), d.get("symbol") or ""),
            "currency": _ps_clean(d.get("currency"), limit=16) or "",
            "soft_cap": _ps_amount(d.get("soft_cap"), chain) or "N/A",
            "hard_cap": _ps_amount(d.get("hard_cap"), chain) or "No Hard Cap",
            "raised": (_ps_amount(d.get("raised"), chain) or _ps_zero(chain)) if live else "",
            "min_buy": _ps_amount(d.get("min_buy"), chain) or "No Min Buy",
            "max_buy": _ps_amount(d.get("max_buy"), chain) or "No Max Buy",
            "starts": (kind + " is live") if live else (_ps_time(d.get("start_time")) or "N/A"),
            "ends": _ps_time(d.get("end_time")) or "N/A",
            "presale_rate": _ps_clean(d.get("rate")) or "",
            "listing_rate": _ps_clean(d.get("listing_rate")) or "",
            "tokens_for_sale": _ps_supply(d.get("total_token"), d.get("symbol") or "") or "",
            "liquidity": _ps_clean(d.get("liquidity")) or "",
            "lp_lock": _ps_clean(d.get("lock_time")) or "",
            "token_ca": html.escape(_tok_early) if (_tok_early and _tok_early.lower() != (rec.get("address","") or "").lower()) else "",
            "sale_address": html.escape(rec.get("address", "") or ""),
            "buy_link": pool, "caller_post_link": f"https://t.me/{channel}/{msg_id}" if channel and msg_id else "",
            "chain_emoji": _cem,
        })
        if rendered is not None:
            return rendered

    # ── DEFAULT DETAILS TEMPLATE (owner 2026-10-02) ──────────────────────────
    def E(eid, fb):
        return _cp_pe(eid, fb) if premium else fb

    R   = E(CP_DET_ROW_ID, "🧀")                       # row emoji (was 🚀)
    CHE = E(CP_DET_CHAIN_IDS.get(chain, CP_DET_CHAIN_IDS["BSC"]), "🧀")
    sym = str(d.get("symbol") or "").strip().lstrip("$")
    handle = html.escape(_display_handle(channel))

    def row2(label, val):
        return f"{R}<b>{label}:</b> {val}\n" if val else ""

    t  = f"{CHE} <b>CHEESEPAD Project Details</b> {CHE}\n\n"
    t += (f"<b>@{handle} has posted about the CheesePad token "
          f"{('$' + html.escape(sym)) if sym else html.escape(str(name))}. "
          f"Below, we’re sharing some information about the token with you.</b>\n\n")

    t += f"{E(CP_DET_HDR_PROJECT, '🧀')} <b>PROJECT DETAILS</b>\n\n"
    t += f'{R}<b>Project:</b> <a href="{pool}">{html.escape(str(name))}</a>\n'
    t += row2("Caller", f"@{handle}")
    t += row2("Chain", html.escape(chain) if chain else "")
    t += row2("Sale Type", _cp_sale_type(d, info))
    t += row2("Token", html.escape(str(d.get("symbol") or name)))
    t += row2("Sale Currency", html.escape(_ps_clean(d.get("currency"), limit=16) or ""))
    t += "\n"

    t += f"{E(CP_DET_HDR_SALE, '🧀')} <b>SALE DETAILS</b>\n\n"
    t += row2("Soft Cap", _ps_amount(d.get("soft_cap"), chain) or "No Soft Cap")
    t += row2("Hard Cap", _ps_amount(d.get("hard_cap"), chain) or "No Hard Cap")
    _raised = _ps_amount(d.get("raised"), chain)
    if live or _raised:
        t += row2("Raised", _raised or _ps_zero(chain))
    t += row2("Min Buy", _ps_amount(d.get("min_buy"), chain) or "No Min Buy")
    t += row2("Max Buy", _ps_amount(d.get("max_buy"), chain) or "No Max Buy")
    t += "\n"

    tk = ""
    tk += row2("Presale Rate", html.escape(_ps_clean(d.get("rate")) or ""))
    tk += row2("Listing Rate", html.escape(_ps_clean(d.get("listing_rate")) or ""))
    tk += row2("Liquidity", html.escape(_ps_clean(d.get("liquidity")) or ""))
    tk += row2("LP Lock", html.escape(_ps_clean(d.get("lock_time")) or ""))
    if tk:
        t += f"{E(CP_DET_HDR_TOKENO, '🧀')} <b>TOKENOMICS</b>\n\n" + tk + "\n"

    addr_blocks = []
    tok = d.get("token") or ""
    if tok and tok.lower() != (rec.get("address", "") or "").lower():
        addr_blocks.append(f"{E(CP_DET_TOKEN_CA, '🧀')} <b>TOKEN CA:</b>\n\n<code>{html.escape(tok)}</code>")
    if rec.get("address"):
        addr_blocks.append(f"{E(CP_DET_SALE_ADDR, '🧀')} <b>Sale Address:</b>\n\n<code>{html.escape(rec.get('address', ''))}</code>")
    if addr_blocks:
        t += "<blockquote>" + "\n\n".join(addr_blocks) + "</blockquote>\n\n"

    t += f'{E(CP_DET_BUY, "🧀")}<a href="{pool}">Buy on CheesePad</a>'
    if channel and msg_id:
        t += f'  |  {E(CP_DET_CALLER, "🧀")}<a href="https://t.me/{channel}/{msg_id}">Caller Post</a>'
    return t


_CHEESEPAD_SEEN = set()


async def send_cheesepad_alert(bot, channel, msg_id, info, post_text="", force=False,
                               preview_to=None, prefetched=None):
    """Build + post the CheesePad alert with premium emojis and media."""
    key = f"CP|{(info.get('address') or info.get('url') or '').lower()}"
    try:
        if not force and not preview_to and key in _CHEESEPAD_SEEN:
            logger.info(f"CheesePad duplicate skipped: {key}")
            return False
        _CHEESEPAD_SEEN.add(key)

        if prefetched is not None:
            details = prefetched
        else:
            details = await asyncio.to_thread(fetch_launchpad_details_sync, info, post_text)
            if not force and not preview_to and await _lp_gate(bot, "CheesePad", channel, msg_id, info, post_text, details):
                return True      # post ruki: bot khud dhoond raha / owner se puch raha

        pid     = _ps_store(info, details, channel, msg_id)
        text, emoji_ids = build_cheesepad_post(channel, msg_id, info, details, pid)

        if preview_to:
            try:
                await bot.send_message(preview_to, text, parse_mode="HTML",
                                       disable_web_page_preview=True)
            except Exception as e:
                await bot.send_message(preview_to, f"Preview failed: {e}")
            return True

        # CheesePad posts use ONLY CheesePad media. Never fall back to the
        # PinkSale rotation — that made CheesePad tokens show PinkSale videos.
        media = _cp_next_media()
        sent  = None
        # forced_pack → 🔮KOL must use the CheesePad KOL emoji, never the
        # rotating alert pack's KOL emoji.
        cp_pack = {"name": "cheesepad", "kol": CP_EMOJI["kol"],
                   "bot": CP_EMOJI["details"], "mae": 0}
        if media and media.get("file_id") and userbot_client:
            try:
                sent = await _userbot_send_media_with_emoji(
                    bot, TARGET_CHANNEL, media["file_id"],
                    media.get("type", "video"), text, emoji_ids,
                    forced_pack={})
            except Exception as e:
                logger.warning(f"CheesePad userbot media send failed: {e}")
        if not sent and userbot_client:
            sent = await _userbot_send_with_premium_emoji(
                TARGET_CHANNEL, text, emoji_ids, link_preview=False,
                forced_pack={})
        sent_id = getattr(sent, "id", None)

        if not sent:
            plain = text.replace("🔮", "🧀")
            m = await bot.send_message(TARGET_CHANNEL, plain, parse_mode="HTML",
                                       disable_web_page_preview=True)
            sent_id = m.message_id

        logger.info(f"🧀 CheesePad alert posted @{channel} pid={pid} msg={sent_id}")
        await _ps_forward_to_caller(bot, channel, sent_id)
        _ps_watch_add(pid, info, details, channel)
        _cp_hc_watch_add(bot, pid, info, details, channel, msg_id)    # hardcap-filled watcher (msg_id = caller ki original post → KOL link sahi)
        return True
    except Exception as e:
        _CHEESEPAD_SEEN.discard(key)
        logger.error(f"send_cheesepad_alert failed for {key}: {e}", exc_info=True)
        return False


# ═══════════════════════════════════════════════════════════════════════════
# CHEESEPAD — HARDCAP FILLED VIDEO  (owner 2026-10-20)
#   Base video (si_hardcap_filled_v3.mp4) ko har post ke liye patch karta hai:
#     • $SI              → project ka symbol
#     • N BNB / Raised / X BNB  → project ka hardcap (count-up animation same rehti hai)
#     • N participants   → real participants (nahi mile to wo text hide)
#     • right wala NEELA logo → caller channel ka profile logo
#   Baqi sab (wizard logo, HARDCAP FILLED, bar, glow) base video se hi aata hai.
#
#   Railway load: ~90 frames numpy/PIL + 1 ffmpeg encode (ultra-light, 1 time me 1 render,
#   nice 10, 2 threads). File post hote hi delete (cp_hc_cleanup) + purani temp dirs sweep.
#
#   Is block ko launchpad.py me cp_hardcap_patch.py ke UPAR/NEECHE paste karo
#   (bot.py sab ko ek namespace me load karta hai, is liye imports yahin hain).
# ═══════════════════════════════════════════════════════════════════════════
import os, re, io, sys, time, shutil, tempfile, threading, subprocess, base64
np = Image = ImageDraw = ImageFont = None            # lazy: numpy/Pillow na hon to bot import fail nahi hoga
_HCV_FFMPEG = None


def _hcv_pip(pkg):
    try:
        subprocess.run([sys.executable, "-m", "pip", "install", "--quiet", "--disable-pip-version-check", pkg],
                       timeout=240, check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        pass


def _hcv_setup():
    """numpy + Pillow + ffmpeg ready karo (na hon to khud pip install). False = nahi ho saka."""
    global np, Image, ImageDraw, ImageFont, _HCV_FFMPEG
    if np is None or Image is None:
        for attempt in (0, 1):
            try:
                import numpy as _np
                from PIL import Image as _I, ImageDraw as _D, ImageFont as _F
                np, Image, ImageDraw, ImageFont = _np, _I, _D, _F
                break
            except Exception:
                if attempt == 0:
                    _hcv_pip("numpy"); _hcv_pip("Pillow")
        if np is None:
            return False
    if not _HCV_FFMPEG:
        _HCV_FFMPEG = shutil.which("ffmpeg")
        if not _HCV_FFMPEG:
            for attempt in (0, 1):
                try:
                    import imageio_ffmpeg
                    _HCV_FFMPEG = imageio_ffmpeg.get_ffmpeg_exe()
                    break
                except Exception:
                    if attempt == 0:
                        _hcv_pip("imageio-ffmpeg")
    return bool(_HCV_FFMPEG)


def _hcv_base_video():
    """Base video: root/assets me ho to wahi, warna code ke andar embedded copy temp me likh do."""
    for p in (HCV_BASE_VIDEO,
              os.path.join(_HCV_HERE, "si_hardcap_filled_v3.mp4"),
              os.path.join(os.getcwd(), "si_hardcap_filled_v3.mp4")):
        if p and os.path.isfile(p):
            return p
    emb = globals().get("_HCV_EMBED_B64")
    if not emb:
        return None
    p = os.path.join(tempfile.gettempdir(), "hcbase_v3.mp4")
    if not (os.path.isfile(p) and os.path.getsize(p) > 5000):
        with open(p, "wb") as fh:
            fh.write(base64.b64decode(emb))
    return p

try:
    _HCV_HERE = os.path.dirname(os.path.abspath(__file__))
except NameError:                                   # exec()-loaded namespace
    _HCV_HERE = os.getcwd()

# repo me ye 2 cheezein rakho:  assets/si_hardcap_filled_v3.mp4  aur  assets/fonts/Poppins-*.ttf
HCV_BASE_VIDEO = os.environ.get("CP_HC_BASE_VIDEO") or os.path.join(_HCV_HERE, "assets", "si_hardcap_filled_v3.mp4")  # optional; na ho to embedded copy
HCV_FONT_DIRS  = [os.environ.get("CP_HC_FONT_DIR") or "",
                  os.path.join(_HCV_HERE, "assets", "fonts"),
                  os.path.join(_HCV_HERE, "fonts"),
                  _HCV_HERE,
                  "/usr/share/fonts/truetype/google-fonts"]

HCV_W, HCV_H = 1080, 462
HCV_SYM_COLOR = (253, 212, 9)
HCV_TAN_COLOR = (192, 176, 120)
HCV_WHITE     = (255, 255, 255)

_HCV_LOCK = threading.Lock()          # ek waqt me sirf ek render → Railway pe spike nahi


# ── fonts ────────────────────────────────────────────────────────────────────
_HCV_FONT_CACHE = {}

def _hcv_font(weight, size):
    key = (weight, int(size))
    if key in _HCV_FONT_CACHE:
        return _HCV_FONT_CACHE[key]
    font = None
    for fn in (f"Poppins-{weight}.ttf", "Poppins-Bold.ttf"):
        for d in HCV_FONT_DIRS:
            p = os.path.join(d, fn) if d else ""
            if p and os.path.isfile(p):
                font = ImageFont.truetype(p, int(size)); break
        if font:
            break
    if font is None:
        for p in ("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
                  "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf"):
            if os.path.isfile(p):
                font = ImageFont.truetype(p, int(size)); break
    if font is None:
        font = ImageFont.load_default()
    _HCV_FONT_CACHE[key] = font
    return font


# ── text helpers ─────────────────────────────────────────────────────────────
def _hcv_text_layer(w, h, text, font, xy, anchor):
    """L-mode mask (float 0..1) jisme text draw hua ho."""
    im = Image.new("L", (w, h), 0)
    ImageDraw.Draw(im).text(xy, text, font=font, fill=255, anchor=anchor)
    return np.asarray(im, dtype=np.float32) / 255.0


def _hcv_blend(frame, x0, y0, mask, color, alpha):
    """frame[y0:y0+h, x0:x0+w] me color ko mask*alpha ke saath blend."""
    h, w = mask.shape
    reg = frame[y0:y0 + h, x0:x0 + w].astype(np.float32)
    m = (mask * alpha)[..., None]
    col = np.array(color, dtype=np.float32)[None, None, :]
    frame[y0:y0 + h, x0:x0 + w] = (reg * (1 - m) + col * m).astype(np.uint8)


def _hcv_cover(frame, x0, y0, x1, y1):
    """Purana text mita do: har row ko rect ke right-edge ke pixel se bhar do."""
    x1 = min(x1, HCV_W - 2)
    col = frame[y0:y1, x1 + 1:x1 + 2, :]
    frame[y0:y1, x0:x1, :] = col


def _hcv_fmt_amount(hard_num, p, decimals):
    v = hard_num * p
    if p >= 0.999:
        v = hard_num
    if decimals <= 0:
        return f"{int(v):,}" if hard_num >= 1000 else f"{int(v)}"
    return f"{v:.{decimals}f}".rstrip("0").rstrip(".") if p >= 0.999 else f"{v:.{decimals}f}"


def _hcv_parse_cap(hard_txt, cur_fallback="BNB"):
    """'40 BNB' / '1,250.5 ETH' → (40.0, 'BNB', decimals)."""
    s = str(hard_txt or "").strip()
    m = re.match(r"^\s*([\d,]*\.?\d+)\s*([A-Za-z0-9\.\$]*)", s)
    if not m:
        return None, cur_fallback, 0
    num_s = m.group(1).replace(",", "")
    try:
        num = float(num_s)
    except Exception:
        return None, cur_fallback, 0
    dec = len(num_s.split(".")[1]) if "." in num_s else 0
    return num, (m.group(2) or cur_fallback).upper(), min(dec, 3)


def _hcv_clean_symbol(sym, fallback="TOKEN"):
    s = re.sub(r"[^A-Za-z0-9\.\-_]", "", str(sym or "").lstrip("$"))[:14]
    return s or fallback


# ── logo ─────────────────────────────────────────────────────────────────────
def _hcv_prep_logo(logo_bytes, diameter, ss=4):
    """Caller logo → gol (circle) RGBA, diameter x diameter. None agar decode fail."""
    try:
        im = Image.open(io.BytesIO(logo_bytes)).convert("RGBA")
    except Exception:
        return None
    w, h = im.size
    s = min(w, h)
    im = im.crop(((w - s) // 2, (h - s) // 2, (w - s) // 2 + s, (h - s) // 2 + s))
    big = diameter * ss
    im = im.resize((big, big), Image.LANCZOS)
    mask = Image.new("L", (big, big), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, big - 1, big - 1), fill=255)
    im.putalpha(Image.composite(im.getchannel("A"), Image.new("L", (big, big), 0), mask))
    return im.resize((diameter, diameter), Image.LANCZOS)


def _hcv_paste_logo(frame, logo_cache, logo_bytes, cx, cy, r, alpha):
    d = int(round(2 * r))
    if d < 8:
        return
    lg = logo_cache.get(d)
    if lg is None:
        lg = _hcv_prep_logo(logo_bytes, d)
        if lg is None:
            return
        logo_cache[d] = lg
    x0, y0 = int(round(cx - d / 2)), int(round(cy - d / 2))
    if x0 < 0 or y0 < 0 or x0 + d > HCV_W or y0 + d > HCV_H:
        return
    arr = np.asarray(lg, dtype=np.float32)
    a = (arr[..., 3:4] / 255.0) * alpha
    reg = frame[y0:y0 + d, x0:x0 + d].astype(np.float32)
    frame[y0:y0 + d, x0:x0 + d] = (reg * (1 - a) + arr[..., :3] * a).astype(np.uint8)


# ── per-frame patch ──────────────────────────────────────────────────────────
_BLUE_REF = {"n": None}


def _hcv_patch_frame(f, st):
    """f: (H,W,3) uint8 (in-place). st: dict(sym, hard_num, cur, dec, parts, logo, cache)."""
    R = f[:, :, 0].astype(np.int16)
    G = f[:, :, 1].astype(np.int16)
    B = f[:, :, 2].astype(np.int16)

    # 1) right logo (neela disc) ----------------------------------------------
    if st["logo"]:
        sub = (B[:210, 840:1060] > 150) & (R[:210, 840:1060] < 90) & (G[:210, 840:1060] < 120)
        n = int(sub.sum())
        if n > 300:
            ys, xs = np.where(sub)
            x0, x1, y0, y1 = xs.min() + 840, xs.max() + 840, ys.min(), ys.max()
            cx, cy = (x0 + x1) / 2.0, (y0 + y1) / 2.0
            r = max(x1 - x0, y1 - y0) / 2.0 + 1.0
            a = min(1.0, n / 2000.0)          # poora disc (~2300 px) = full opaque, fade-in me halka
            _hcv_paste_logo(f, st["cache"], st["logo"], cx, cy, r, a)

    # 2) $SYMBOL --------------------------------------------------------------
    rx0, ry0, rx1, ry1 = 270, 62, 860, 152
    TX0 = 281 - rx0                      # left-logo ka glow (x<281) text nahi hai
    reg = R[ry0:ry1, rx0:rx1]
    mk = reg > 60
    mk[:, :TX0] = False
    if mk.sum() > 40:
        ys, xs = np.where(mk)
        dx, dy = int(xs.min() + rx0 - 280), int(ys.min() + ry0 - 80)
        a = min(1.0, float(reg[:, TX0:].max()) / 250.0)
        # sirf purane text ke pixel (thoda phailake) kaale karo → glow par box nahi banta
        dm = mk.copy()
        for _ in range(3):
            t = dm.copy()
            t[1:, :] |= dm[:-1, :]; t[:-1, :] |= dm[1:, :]
            t[:, 1:] |= dm[:, :-1]; t[:, :-1] |= dm[:, 1:]
            dm = t
        sreg = f[ry0:ry1, rx0:rx1]
        sreg[dm] = (6, 6, 4)
        txt = "$" + st["sym"]
        size = 64
        font = _hcv_font("Bold", size)
        while font.getlength(txt) > 540 and size > 28:
            size -= 2
            font = _hcv_font("Bold", size)
        mask = _hcv_text_layer(rx1 - rx0, ry1 - ry0, txt, font,
                               (280 + dx - rx0, 131 + dy - ry0), "ls")
        _hcv_blend(f, rx0, ry0, mask, HCV_SYM_COLOR, a)

    # 3) card texts -----------------------------------------------------------
    col = f[240:462, 300, :].astype(np.int16)
    hit = np.where((col[:, 0] > 170) & (col[:, 1] > 130) & (col[:, 2] < 90))[0]
    if len(hit):
        ty = int(hit[0]) + 240
        # bar fill p (0..1)
        brow = f[ty + 76, 148:938, 0].astype(np.int16)
        dark = np.where(brow < 90)[0]
        p = 1.0 if len(dark) == 0 else float(dark[0]) / 790.0
        p = max(0.0, min(1.0, p))
        if p > 0.985:
            p = 1.0

        # card text visibility (fade-in)
        amt_reg = f[ty + 14:ty + 52, 312:620, :]
        ca = min(1.0, float(amt_reg.min(axis=2).max()) / 230.0)

        # amount "N BNB"
        _hcv_cover(f, 312, ty + 14, 620, ty + 52)
        amt = f"{_hcv_fmt_amount(st['hard_num'], p, st['dec'])} {st['cur']}"
        # baseline = ty + 46  → mask coords: (ty+46) - (ty+14) = 32
        m = _hcv_text_layer(308, 38, amt, _hcv_font("Bold", 36), (319 - 312, 32), "ls")
        _hcv_blend(f, 312, ty + 14, m, HCV_WHITE, ca)

        # "Raised / X BNB"
        cap_txt = f"{_hcv_fmt_amount(st['hard_num'], 1.0, st['dec'])} {st['cur']}"
        ra = f[ty + 92:ty + 132, 136:470, :]
        rca = min(1.0, float(ra.max()) / 190.0)
        _hcv_cover(f, 136, ty + 92, 470, ty + 132)
        m = _hcv_text_layer(334, 40, f"Raised / {cap_txt}", _hcv_font("Medium", 25), (139 - 136, 123 - 92), "ls")
        _hcv_blend(f, 136, ty + 92, m, HCV_TAN_COLOR, rca)

        # participants (right aligned @ x=940)
        _hcv_cover(f, 690, ty + 92, 946, ty + 132)
        if st["parts"] is not None:
            n_now = st["parts"] if p >= 1.0 else int(round(st["parts"] * p))
            m = _hcv_text_layer(256, 40, f"{n_now} {'participant' if n_now == 1 else 'participants'}",
                                _hcv_font("Medium", 25), (939 - 690, 123 - 92), "rs")
            _hcv_blend(f, 690, ty + 92, m, HCV_TAN_COLOR, rca)


# ── render ───────────────────────────────────────────────────────────────────
def _hcv_sweep(max_age=900):
    try:
        now = time.time()
        base = tempfile.gettempdir()
        for n in os.listdir(base):
            if n.startswith("cphc_"):
                p = os.path.join(base, n)
                if now - os.path.getmtime(p) > max_age:
                    shutil.rmtree(p, ignore_errors=True)
    except Exception:
        pass


def cp_hc_render_sync(symbol, hard_cap_txt, participants, logo_bytes, currency=None):
    """Blocking. Returns mp4 path (temp) ya None. Call karne ke baad cp_hc_cleanup(path) zaroor."""
    if not _hcv_setup():
        return None
    base_video = _hcv_base_video()
    if not base_video:
        return None
    hard_num, cur, dec = _hcv_parse_cap(hard_cap_txt, currency or "BNB")
    if not hard_num or hard_num <= 0:
        return None
    if currency:
        cur = str(currency).upper()
    _hcv_sweep()
    out_dir = tempfile.mkdtemp(prefix="cphc_")
    out = os.path.join(out_dir, "hardcap.mp4")
    st = {"sym": _hcv_clean_symbol(symbol), "hard_num": hard_num, "cur": cur, "dec": dec,
          "parts": (int(participants) if participants is not None else None),
          "logo": logo_bytes, "cache": {}, "blue_ref": None}
    fsz = HCV_W * HCV_H * 3
    dec_p = enc_p = None
    try:
        with _HCV_LOCK:
            nice = lambda: os.nice(10)
            dec_p = subprocess.Popen(
                [_HCV_FFMPEG, "-v", "error", "-threads", "2", "-i", base_video,
                 "-f", "rawvideo", "-pix_fmt", "rgb24", "-"],
                stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, preexec_fn=nice)
            enc_p = subprocess.Popen(
                [_HCV_FFMPEG, "-v", "error", "-y", "-f", "rawvideo", "-pix_fmt", "rgb24",
                 "-s", f"{HCV_W}x{HCV_H}", "-r", "30", "-i", "-",
                 "-c:v", "libx264", "-preset", "veryfast", "-crf", "23", "-threads", "2",
                 "-pix_fmt", "yuv420p", "-movflags", "+faststart", "-an", out],
                stdin=subprocess.PIPE, stderr=subprocess.DEVNULL, preexec_fn=nice)
            nfr = 0
            while True:
                buf = dec_p.stdout.read(fsz)
                if len(buf) < fsz:
                    break
                fr = np.frombuffer(buf, dtype=np.uint8).reshape(HCV_H, HCV_W, 3).copy()
                _hcv_patch_frame(fr, st)
                enc_p.stdin.write(fr.tobytes())
                nfr += 1
            enc_p.stdin.close()
            enc_p.wait(timeout=60)
            dec_p.wait(timeout=10)
        if nfr < 30 or not os.path.isfile(out) or os.path.getsize(out) < 5000:
            shutil.rmtree(out_dir, ignore_errors=True)
            return None
        return out
    except Exception:
        for p_ in (dec_p, enc_p):
            try:
                if p_ and p_.poll() is None:
                    p_.kill()
            except Exception:
                pass
        shutil.rmtree(out_dir, ignore_errors=True)
        return None


def cp_hc_cleanup(path):
    """Post hone ke foran baad: video + uska temp folder delete."""
    try:
        if path and os.path.basename(os.path.dirname(path)).startswith("cphc_"):
            shutil.rmtree(os.path.dirname(path), ignore_errors=True)
        elif path and os.path.isfile(path):
            os.remove(path)
    except Exception:
        pass


# ── caller ka logo ───────────────────────────────────────────────────────────
async def _cp_hc_fetch_logo(bot, channel):
    """Caller channel ki profile photo (bytes) ya None. 1) Bot API  2) userbot."""
    ch = (channel or "").lstrip("@")
    if not ch:
        return None
    try:
        chat = await bot.get_chat(f"@{ch}")
        ph = getattr(chat, "photo", None)
        if ph:
            tf = await bot.get_file(ph.big_file_id)
            bio = io.BytesIO()
            await tf.download_to_memory(bio)
            data = bio.getvalue()
            if data:
                return data
    except Exception as e:
        logger.info(f"cp_hc logo (bot api) @{ch}: {e}")
    try:
        if userbot_client:
            data = await userbot_client.download_profile_photo(ch, file=bytes)
            if data:
                return data
    except Exception as e:
        logger.info(f"cp_hc logo (userbot) @{ch}: {e}")
    return None


async def cp_hc_make_video(bot, w, snap):
    """Watch-entry + snapshot se video banao. None = base video/ffmpeg nahi → purana media use hoga."""
    try:
        d = snap["d"]
        sym = str(d.get("symbol") or d.get("name") or "").strip()
        logo = await _cp_hc_fetch_logo(bot, w.get("channel"))
        return await asyncio.to_thread(
            cp_hc_render_sync, sym, d.get("hard_cap"), snap.get("participants"),
            logo, d.get("currency"))
    except Exception as e:
        logger.warning(f"cp_hc video build failed: {e}")
        return None


# ═══════════════════════════════════════════════════════════════════════════
# CHEESEPAD — HARDCAP FILLED ALERT  (owner 2026-10-20)
#   Jab Fairlaunch / WL-presale / presale ki hardcap fill ho jaye:
#     1) bot main channel (TARGET_CHANNEL) pe template post karta hai
#     2) wohi post caller-channel ke owner ke DM me forward hoti hai
#        (same mechanism jo CheesePad alert ke liye _ps_forward_to_caller use karta hai)
#   Is block ko launchpad.py me SABSE NEECHE (send_cheesepad_alert ke baad) paste karo.
#   Koi import nahi chahiye — bot.py sab pieces ko ek namespace me load karta hai.
# ═══════════════════════════════════════════════════════════════════════════

CP_HC_E_HEADER     = 5960818405257781348   # header ki dono taraf
CP_HC_E_TOKENOMICS = 5904696991018917965
CP_HC_E_DETAIL     = 5904447835671108691   # 5 details wali emoji
CP_HC_E_CA         = 5773971281883965193

CP_HC_POLL_SECS    = 45          # live sale ko kitni dair baad dobara check kare
CP_HC_PRE_START_S  = 600         # start se pehle itni dair baad check
CP_HC_GIVE_UP_S    = 6 * 3600    # sale end ke baad itni dair tak hi dekhna
CP_HC_FILL_RATIO   = 0.999       # raised >= hardcap * 0.999  → filled

_CP_HC_TASK = None


def _cp_hc_e(eid, fb="🧀"):
    return f'<tg-emoji emoji-id="{eid}">{fb}</tg-emoji>'


def _cp_hc_plain(text):
    """Bot-API fallback: premium <tg-emoji> tags → normal emoji."""
    return re.sub(r'<tg-emoji emoji-id="\d+">(.*?)</tg-emoji>', r'\1', text)


def _cp_hc_human(txt):
    """'7,000,000,000,000 SI' → '7 Trillion SI'. 1M se neeche wale numbers commas me rehte hain."""
    s = str(txt or "").strip()
    m = re.match(r'^\s*([\d,]+(?:\.\d+)?)\s*(.*)$', s)
    if not m:
        return html.escape(s)
    try:
        n = float(m.group(1).replace(",", ""))
    except Exception:
        return html.escape(s)
    sym = m.group(2).strip()
    for div, name in ((1e15, "Quadrillion"), (1e12, "Trillion"), (1e9, "Billion"), (1e6, "Million")):
        if n >= div:
            t = f"{n / div:.2f}".rstrip("0").rstrip(".")
            return html.escape(f"{t} {name} {sym}".strip())
    t = (f"{n:,.4f}" if n < 1000 else f"{n:,.2f}").rstrip("0").rstrip(".")
    return html.escape(f"{t} {sym}".strip())


def _cp_hc_deep_find(obj, names, depth=0):
    """Raw JSON me se pehli matching key (participants/contributors...) ki numeric value."""
    if depth > 5:
        return None
    if isinstance(obj, dict):
        for k, v in obj.items():
            if str(k).lower() in names and isinstance(v, (int, float)) and not isinstance(v, bool):
                return int(v)
            if str(k).lower() in names and isinstance(v, list):
                return len(v)
        for v in obj.values():
            r = _cp_hc_deep_find(v, names, depth + 1)
            if r is not None:
                return r
    elif isinstance(obj, list):
        for v in obj[:50]:
            r = _cp_hc_deep_find(v, names, depth + 1)
            if r is not None:
                return r
    return None


_CP_HC_PART_KEYS = {"participants", "participantcount", "participantscount", "totalparticipants",
                    "contributors", "contributorcount", "contributorscount", "totalcontributors",
                    "investors", "investorcount", "investorscount", "totalinvestors",
                    "buyers", "buyercount", "holders", "holdercount"}


_CP_HC_PART_SUBSTR = ("particip", "contributor", "investor", "buyer")
_CP_HC_PART_BAD    = ("max", "min", "amount", "limit", "address", "whitelist", "percent", "reward", "vesting")
_CP_HC_PART_PATHS  = ("/launchpad/contributors", "/launchpad/participants", "/launchpad/contributions",
                      "/launchpad/investors", "/launchpad/buyers", "/launchpad/holders",
                      "/microsale/contributors", "/microsale/participants", "/microsale/contributions")
_CP_HC_PAGING      = ("page", "pages", "totalpages", "hasnext", "nextcursor", "cursor", "offset", "next")


def _cp_hc_fuzzy_count(obj, depth=0):
    """full_info JSON me 'participants/contributors/investors/buyers' jaisi key ka count (number ya list-len)."""
    if depth > 5:
        return None
    if isinstance(obj, dict):
        for k, v in obj.items():
            kl = str(k).lower()
            if any(x in kl for x in _CP_HC_PART_SUBSTR) and not any(b in kl for b in _CP_HC_PART_BAD):
                if isinstance(v, bool):
                    continue
                if isinstance(v, (int, float)) and v >= 0:
                    return int(v)
                if isinstance(v, str) and v.strip().isdigit():
                    return int(v.strip())
                if isinstance(v, list):
                    return len(v)
        for v in obj.values():
            r = _cp_hc_fuzzy_count(v, depth + 1)
            if r is not None:
                return r
    elif isinstance(obj, list):
        for v in obj[:50]:
            r = _cp_hc_fuzzy_count(v, depth + 1)
            if r is not None:
                return r
    return None


def _cp_hc_count_from_json(j):
    """Alag endpoint ke response se buyers ginti. Sirf bharosemand count (total key ya non-paginated list)."""
    if isinstance(j, dict):
        for k, v in j.items():
            if str(k).lower() in ("total", "totalcount", "count", "totalitems", "total_count") \
                    and isinstance(v, (int, float)) and not isinstance(v, bool):
                return int(v)
        r = _cp_hc_fuzzy_count(j)
        if r is not None:
            return r
        paged = any(str(k).lower() in _CP_HC_PAGING for k in j.keys())
        for k in ("data", "items", "result", "results", "list", "rows"):
            v = j.get(k)
            if isinstance(v, list) and not paged:
                return len(v)
            if isinstance(v, dict):
                r = _cp_hc_count_from_json(v)
                if r is not None:
                    return r
    elif isinstance(j, list):
        return len(j)
    return None


def _cp_hc_participants_http(addr, chain_id, microsale):
    """full_info me count na ho to alag endpoints try karo. Jo path chal gaya wo cfg me yaad."""
    cached = cfg_get("cp_hc_part_path", "") or ""
    paths = ([cached] if cached else []) + [p for p in _CP_HC_PART_PATHS if p != cached]
    for path in paths:
        if ("microsale" in path) != bool(microsale):
            continue
        try:
            key = "fundManager" if microsale else "poolAddress"
            r = requests.get(_CP_API_BASE + path, params={"chainId": chain_id, key: addr},
                             headers=_LP_UA, timeout=10)
            if r.status_code != 200:
                continue
            n = _cp_hc_count_from_json(r.json())
            if n is not None:
                if path != cached:
                    cfg_set("cp_hc_part_path", path)
                    logger.info(f"cp_hc participants endpoint found: {path} → {n}")
                return n
        except Exception:
            continue
    return None


def _cp_hc_snapshot(info: dict):
    """CheesePad full_info ka raw JSON + mapped details + participants. (blocking → to_thread)"""
    addr = (info.get("address") or "").strip()
    if not addr.startswith("0x"):
        return None
    chain = (info.get("chain") or "").upper()
    ids = []
    cid = _CP_CHAIN_IDS.get(chain)
    if cid:
        ids.append(cid)
    for c in (56, 1, 8453, 42161, 137, 43114, 204, 1116):
        if c not in ids:
            ids.append(c)
    url = (info.get("url") or "").lower()
    paths = ["/microsale/full_info", "/launchpad/full_info"] if "microsale" in url \
        else ["/launchpad/full_info", "/microsale/full_info"]
    for path in paths:
        for c in ids:
            try:
                key = "fundManager" if "microsale" in path else "poolAddress"
                r = requests.get(_CP_API_BASE + path, params={"chainId": c, key: addr},
                                 headers=_LP_UA, timeout=10)
                if r.status_code != 200:
                    continue
                raw = r.json()
            except Exception:
                continue
            mapped = _cp_map_pool(raw if isinstance(raw, dict) else {})
            if mapped:
                parts = _cp_hc_deep_find(raw, _CP_HC_PART_KEYS)
                if parts is None:
                    parts = _cp_hc_fuzzy_count(raw)
                if parts is None:
                    parts = _cp_hc_participants_http(addr, c, "microsale" in path)
                return {"raw": raw, "d": mapped, "participants": parts}
    return None


def _cp_hc_is_filled(d: dict) -> bool:
    hard = _ps_num(d.get("hard_cap"))
    raised = _ps_num(d.get("raised"))
    if not hard or hard <= 0 or raised is None:
        return False
    return raised >= hard * CP_HC_FILL_RATIO


def build_cp_hardcap_post(channel, pid, msg_id, info, d, participants, w):
    """Owner template. Returns (html_text, emoji_ids)."""
    chain = (info.get("chain") or "").upper()
    kind  = "Fairlaunch" if _cp_is_fairlaunch(d, info) else "Presale"   # WL presale bhi "Presale"
    sym   = str(d.get("symbol") or d.get("name") or "").strip().lstrip("$")
    sym_h = html.escape(sym) if sym else "TOKEN"
    handle = html.escape(_display_handle(channel))
    cur = d.get("currency") or _ps_native(chain) or "BNB"
    hard_txt = html.escape(str(d.get("hard_cap") or "").strip()) or f"hard cap"

    # ── caller kab post kia tha ──
    st = (w or {}).get("call_state") or "before_start"
    raised_call = (w or {}).get("raised_at_call") or 0
    sw = kind.lower()
    if st == "before_start":
        intro = f"@{handle} posted ${sym_h} before the {sw} started."
    elif st == "during_live" and raised_call and raised_call > 0:
        intro = (f"@{handle} posted ${sym_h} when the {sw} was live and "
                 f"{html.escape(_cp_fmt_num(raised_call))} {html.escape(cur)} had been raised.")
    else:
        intro = f"@{handle} posted ${sym_h} after the {sw} went live."

    body = (f"{intro} The Hard Cap of {hard_txt} is now fully filled. "
            f"Good luck to everyone who joined.")

    HE = _cp_hc_e(CP_HC_E_HEADER)
    DE = _cp_hc_e(CP_HC_E_DETAIL)
    # jo detail na mile us ki poori line hata do (N/A kabhi nahi likhna)
    rate_lbl = f"{kind} Rate:"
    rows = [
        (rate_lbl,          _cp_hc_human(d.get("rate"))),
        ("Listing Rate:",   _cp_hc_human(d.get("listing_rate"))),
        ("Liquidity:",      html.escape(str(d.get("liquidity") or "").strip())),
        ("Participants:",   html.escape(str(participants)) if participants is not None else ""),
        ("LP Locked:",      html.escape(str(d.get("lock_time") or "").strip())),
    ]
    details = "\n".join(f"{DE}<b>{lbl}</b> {val}" for lbl, val in rows if val)

    ca = html.escape(str(d.get("token") or "").strip())

    det_link  = f"{BOT_LINK}?start=cp_{pid}"
    pool_link = cp_pool_link(info)
    ch_link   = f"https://t.me/{channel}/{msg_id}" if channel and msg_id else TG_CHANNEL_LINK

    t  = f"{HE} <b>HARDCAP FILLED — {kind.upper()} ENDED</b> {HE}\n\n"
    t += f"{body}\n\n"
    if details:
        t += f"{_cp_hc_e(CP_HC_E_TOKENOMICS)} <b>TOKENOMICS</b>\n"
        t += f"<blockquote>{details}</blockquote>\n\n"
    if ca:
        t += f"{_cp_hc_e(CP_HC_E_CA)} <b>TOKEN CA:</b>\n"
        t += f"<blockquote><code>{ca}</code></blockquote>\n\n"
    t += (f'{_cp_hc_e(CP_LINK_DETAILS_ID)}<a href="{det_link}">Details</a>  '
          f'{_cp_hc_e(CP_LINK_CHEESEPAD_ID)}<a href="{pool_link}">CheesePad</a>  '
          f'{_cp_hc_e(CP_LINK_KOL_ID)}<a href="{ch_link}">KOL</a>')
    return t, [CP_EMOJI["cheesepad"]]


def _cp_hc_next_media():
    """Hardcap-filled videos (cfg 'cp_hc_media', rotating). Abhi set nahi to None."""
    med = cfg_get("cp_hc_media", []) or []
    if not med:
        return None
    idx = int(cfg_get("cp_hc_media_index", 0) or 0) % len(med)
    cfg_set("cp_hc_media_index", (idx + 1) % len(med))
    return med[idx]


# ── watch list (cfg key "cp_hc_watch") ───────────────────────────────────────

def _cp_hc_key(info):
    return (info.get("address") or info.get("url") or "").lower()


def _cp_hc_remove(key):
    cur = [x for x in (cfg_get("cp_hc_watch", []) or []) if x.get("key") != key]
    cfg_set("cp_hc_watch", cur)


def _cp_hc_watch_add(bot, pid, info, details, channel, msg_id):
    """send_cheesepad_alert ke baad call hota hai: caller ne kab post kia, ye yahin freeze hota hai."""
    try:
        key = _cp_hc_key(info)
        if not key:
            return
        watch = cfg_get("cp_hc_watch", []) or []
        if any(x.get("key") == key for x in watch):
            return
        now = time.time()
        st = _ps_epoch(details.get("start_time"))
        en = _ps_epoch(details.get("end_time"))
        status = str(details.get("status", "")).lower()
        raised = _ps_num(details.get("raised")) or 0
        if (st and now < st) or status == "upcoming":
            call_state = "before_start"
        elif raised > 0:
            call_state = "during_live"
        else:
            call_state = "live_nothing"
        watch.append({
            "key": key, "pid": pid, "channel": channel, "msg_id": str(msg_id or ""),
            "info": {k: info.get(k, "") for k in ("address", "chain", "url", "platform")},
            "call_state": call_state, "raised_at_call": raised,
            "start_ts": st, "end_ts": en, "added": now, "fails": 0,
        })
        cfg_set("cp_hc_watch", watch[-100:])
        _cp_hc_ensure_loop(bot)
    except Exception as e:
        logger.warning(f"cp_hc watch add failed: {e}")


async def _cp_hc_post(bot, w, snap):
    """Template build → (generated video) → channel post → owner DM forward."""
    info = dict(w["info"])
    text, emoji_ids = build_cp_hardcap_post(
        w.get("channel", ""), w.get("pid"), w.get("msg_id"), info,
        snap["d"], snap.get("participants"), w)

    # Is project ka apna video (caller logo + symbol + hardcap). Fail ho to purana rotating media.
    vid_path = None
    try:
        vid_path = await cp_hc_make_video(bot, w, snap)
    except Exception as e:
        logger.warning(f"cp_hc video gen failed: {e}")
    media = {"file_id": vid_path, "type": "video"} if vid_path else _cp_hc_next_media()

    sent = None
    try:
        if media and media.get("file_id") and userbot_client:
            try:
                sent = await _userbot_send_media_with_emoji(
                    bot, TARGET_CHANNEL, media["file_id"], media.get("type", "video"),
                    text, emoji_ids, forced_pack={})
            except Exception as e:
                logger.warning(f"cp_hc userbot media send failed: {e}")
        if not sent and userbot_client:
            try:
                sent = await _userbot_send_with_premium_emoji(
                    TARGET_CHANNEL, text, emoji_ids, link_preview=False, forced_pack={})
            except Exception as e:
                logger.warning(f"cp_hc userbot text send failed: {e}")
        sent_id = getattr(sent, "id", None)

        if not sent_id:   # bot API fallback (premium emoji nahi)
            plain = _cp_hc_plain(text)
            if media and media.get("file_id"):
                fh = None
                try:
                    fid = media["file_id"]
                    if vid_path:                       # local generated file
                        fh = open(vid_path, "rb"); fid = fh
                    if media.get("type") == "photo":
                        m = await bot.send_photo(TARGET_CHANNEL, photo=fid,
                                                 caption=plain[:1024], parse_mode="HTML")
                    else:
                        m = await bot.send_video(TARGET_CHANNEL, video=fid,
                                                 caption=plain[:1024], parse_mode="HTML",
                                                 width=1080, height=462, duration=3,
                                                 supports_streaming=True)
                    sent_id = m.message_id
                except Exception as e:
                    logger.warning(f"cp_hc media fallback failed: {e}")
                finally:
                    if fh:
                        fh.close()
            if not sent_id:
                m = await bot.send_message(TARGET_CHANNEL, plain, parse_mode="HTML",
                                           disable_web_page_preview=True)
                sent_id = m.message_id
    finally:
        cp_hc_cleanup(vid_path)            # post hote hi temp video delete → Railway disk/cache saaf

    logger.info(f"🧀🎉 CheesePad HARDCAP FILLED posted @{w.get('channel')} "
                f"pid={w.get('pid')} msg={sent_id} video={'gen' if vid_path else 'rotating/none'}")
    # channel owner ke DM me forward (linked KOL owner)
    ok = await _ps_forward_to_caller(bot, w.get("channel"), sent_id)
    if not ok:
        logger.info(f"cp_hc: @{w.get('channel')} ka owner linked nahi / DM forward nahi hua")
    return sent_id


CP_HC_MAX_WAIT_S = 300        # details poori karne ke liye zyada se zyada itna intezar (post delay ok)
CP_HC_RETRY_S    = 30         # har itni dair baad dobara fetch
_CP_HC_INFLIGHT  = set()
_CP_HC_TASKS     = set()


def _cp_hc_missing(snap):
    d = snap.get("d") or {}
    miss = [k for k in ("rate", "listing_rate", "liquidity", "lock_time", "token") if not d.get(k)]
    if snap.get("participants") is None:
        miss.append("participants")
    return miss


async def _cp_hc_complete(w, snap):
    """Missing details ke liye <=5 min dobara fetch. Phir bhi na mile to wo line post me nahi aayegi."""
    deadline = time.time() + CP_HC_MAX_WAIT_S
    while True:
        miss = _cp_hc_missing(snap)
        if not miss or time.time() >= deadline:
            logger.info(f"cp_hc details @{w.get('channel')}: missing={miss or 'none'} (missing lines post se hat jayengi)")
            return snap
        await asyncio.sleep(CP_HC_RETRY_S)
        new = await asyncio.to_thread(_cp_hc_snapshot, w["info"])
        if not new:
            continue
        for k, v in (new.get("d") or {}).items():
            if v not in (None, "", 0) or k not in snap["d"]:
                snap["d"][k] = v
        if new.get("participants") is not None:
            snap["participants"] = new["participants"]
        snap["raw"] = new.get("raw") or snap.get("raw")


async def _cp_hc_finish(bot, w, snap, key):
    try:
        try:
            logger.info(f"cp_hc fill detected {key}: raised={snap['d'].get('raised')} "
                        f"hard={snap['d'].get('hard_cap')} participants={snap.get('participants')} "
                        f"keys={list((snap['raw'].get('pool') or snap['raw']).keys())[:60]}")
        except Exception:
            pass
        snap = await _cp_hc_complete(w, snap)
        await _cp_hc_post(bot, w, snap)              # video pehle banti hai, phir post
        _cp_hc_remove(key)
    except Exception as e:
        logger.error(f"cp_hc post failed {key}: {e}", exc_info=True)
        cur = cfg_get("cp_hc_watch", []) or []
        for x in cur:
            if x.get("key") == key:
                x["fails"] = int(x.get("fails") or 0) + 1
        cfg_set("cp_hc_watch", [x for x in cur if int(x.get("fails") or 0) <= 3])
    finally:
        _CP_HC_INFLIGHT.discard(key)


async def cp_hc_check_once(bot):
    """Har watched project ek bar check. True = abhi bhi watch list me kuch baaki hai."""
    watch = list(cfg_get("cp_hc_watch", []) or [])
    now = time.time()
    for w in watch:
        key = w.get("key")
        try:
            st, en = w.get("start_ts"), w.get("end_ts")
            if en and now > en + CP_HC_GIVE_UP_S:
                _cp_hc_remove(key); continue
            if now - float(w.get("added") or now) > 14 * 86400:
                _cp_hc_remove(key); continue
            if st and now < st - CP_HC_PRE_START_S:
                continue                                  # sale shuru hone me abhi time hai
            if key in _CP_HC_INFLIGHT:
                continue                                  # post/details-wait chal raha hai
            snap = await asyncio.to_thread(_cp_hc_snapshot, w["info"])
            if not snap:
                continue
            d = snap["d"]
            status = str(d.get("status", "")).lower()
            if status in ("cancelled",):
                _cp_hc_remove(key); continue
            if not _cp_hc_is_filled(d):
                await _cp_sc_consider(bot, w, snap, key)      # softcap filled alert (har poll ka snapshot reuse)
            if _cp_hc_is_filled(d):
                if key in _CP_HC_INFLIGHT:
                    continue                       # is ka post/details-wait pehle se chal raha hai
                _CP_HC_INFLIGHT.add(key)
                t_ = asyncio.get_event_loop().create_task(_cp_hc_finish(bot, w, snap, key))
                _CP_HC_TASKS.add(t_)
                t_.add_done_callback(_CP_HC_TASKS.discard)
                continue
            # sale khatam: bina-hardcap Fairlaunch -> "FAIRLAUNCH ENDED" post (video ke saath)
            if not _cp_hc_is_filled(d):
                if await _cp_fe_consider(bot, w, snap, key):
                    continue                       # post chal rahi hai; finish watch hatayega
            # sale khatam ho gayi lekin hardcap fill nahi hui → ab post nahi banta
            if status in ("ended", "completed") and not _cp_hc_is_filled(d):
                _cp_hc_remove(key)
        except Exception as e:
            logger.warning(f"cp_hc check item failed {key}: {e}")
    return bool(cfg_get("cp_hc_watch", []))


async def _cp_hc_loop(bot):
    global _CP_HC_TASK
    try:
        while True:
            more = await cp_hc_check_once(bot)
            if not more:
                break
            await asyncio.sleep(CP_HC_POLL_SECS)
    except asyncio.CancelledError:
        raise
    except Exception as e:
        logger.error(f"cp_hc loop crash: {e}", exc_info=True)
    finally:
        _CP_HC_TASK = None


def _cp_hc_ensure_loop(bot):
    """Loop ek hi chalta hai; redeploy ke baad ps_watch_job isay dobara utha deta hai."""
    global _CP_HC_TASK
    try:
        if _CP_HC_TASK is None or _CP_HC_TASK.done():
            if cfg_get("cp_hc_watch", []):
                _CP_HC_TASK = asyncio.get_event_loop().create_task(_cp_hc_loop(bot))
    except Exception as e:
        logger.warning(f"cp_hc ensure loop failed: {e}")


# ═══════════════════════════════════════════════════════════════════════════
# CHEESEPAD — SOFTCAP FILLED ALERT + VIDEO  (owner 2026-10-20)
#   Fairlaunch / Whitelist presale ka soft cap fill hote hi:
#     1) bot ek video banata hai (SOFTCAP FILLED, project ka symbol, caller ka logo, bar, participants)
#     2) main channel (TARGET_CHANNEL) pe video + template post karta hai
#     3) wohi post caller (linked KOL owner) ke DM me forward hoti hai
#     4) post hote hi temp video/folder delete (Railway disk/RAM par kuch nahi rukta)
#   Ye hardcap watcher (cp_hc_check_once) ke andar chalta hai: har poll ka snapshot reuse hota hai,
#   isliye CheesePad ki koi extra API call nahi lagti. Har project ke liye sirf ek baar.
#   Hard cap bhi usi waqt fill ho to sirf HARDCAP wali post jati hai.
# ═══════════════════════════════════════════════════════════════════════════

SC_E_HEAD     = 5904241625701296987   # "SOFTCAP SUCCESSFULLY FILLED" aur "TIMELINE:" ke aage wali emoji
SC_FILL_RATIO = 0.999                 # raised >= softcap * 0.999 -> filled

_CP_SC_INFLIGHT = set()
_CP_SC_TASKS = set()


def _cp_sc_posted() -> list:
    return list(cfg_get("cp_sc_posted", []) or [])


def _cp_sc_is_filled(d: dict) -> bool:
    soft = _ps_num(d.get("soft_cap"))
    raised = _ps_num(d.get("raised"))
    if not soft or soft <= 0 or raised is None:
        return False
    return raised >= soft * SC_FILL_RATIO


def _cp_sc_applies(d: dict, info: dict) -> bool:
    """Sirf Fairlaunch ya Whitelist presale (public presale par nahi)."""
    try:
        return bool(_cp_is_fairlaunch(d, info) or _cp_sale_type(d, info) == "Whitelist")
    except Exception:
        return False


def _cp_sc_left(end_ts):
    """'5 hours' / '45 minutes' / '2 days' - end_ts na ho to None."""
    if not end_ts:
        return None
    rem = int(end_ts - time.time())
    if rem <= 0:
        return None
    if rem >= 2 * 86400:
        n, u = rem // 86400, "day"
    elif rem >= 3600:
        n, u = rem // 3600, "hour"
    else:
        n, u = max(1, rem // 60), "minute"
    return f"{n} {u}{'' if n == 1 else 's'}"


def build_cp_softcap_post(channel, pid, msg_id, info, d, w):
    """Owner template (2026-10-20). Returns (html_text, emoji_ids)."""
    chain = (info.get("chain") or "").upper()
    kind = "Fairlaunch" if _cp_is_fairlaunch(d, info) else "Presale"
    sw = kind.lower()
    sym = str(d.get("symbol") or d.get("name") or "").strip().lstrip("$")
    sym_h = html.escape(sym) if sym else "TOKEN"
    handle = html.escape(_display_handle(channel))

    soft = _ps_amount(d.get("soft_cap"), chain)
    hard = _ps_amount(d.get("hard_cap"), chain)
    mnb = _ps_amount(d.get("min_buy"), chain)
    mxb = _ps_amount(d.get("max_buy"), chain)
    if d.get("currency"):   # same fallbacks as the "Token Detected" post
        mnb = mnb or "No Min"
        mxb = mxb or "No Max"
        soft = soft or "No Soft Cap"
        hard = hard or "No Hard Cap"
    soft_txt = html.escape(str(d.get("soft_cap") or soft or "soft cap").strip())

    # caller ne kab post kiya tha (hardcap post jaisi hi logic)
    st = (w or {}).get("call_state") or "before_start"
    raised_call = (w or {}).get("raised_at_call") or 0
    cur = d.get("currency") or _ps_native(chain) or "BNB"
    if st == "before_start":
        intro = f"@{handle} posted ${sym_h} before the {sw} started."
    elif st == "during_live" and raised_call and raised_call > 0:
        intro = (f"@{handle} posted ${sym_h} when the {sw} was live and "
                 f"{html.escape(_cp_fmt_num(raised_call))} {html.escape(cur)} had been raised.")
    else:
        intro = f"@{handle} posted ${sym_h} after the {sw} went live."
    body = f"{intro} The Soft Cap of {soft_txt} is now fully filled."

    left = _cp_sc_left(_ps_epoch(d.get("end_time")) or (w or {}).get("end_ts"))
    if left:
        timeline = f"DYOR! Only {left} left until the {sw} ends."
    else:
        timeline = f"DYOR! Keep an eye on the {sw} timeline."

    LBL = _cp_hc_e(CP_LABEL_EMOJI_ID)
    VAL = _cp_hc_e(CP_VALUE_EMOJI_ID)

    det_link = f"{BOT_LINK}?start=cp_{pid}"
    pool_link = cp_pool_link(info)
    ch_link = f"https://t.me/{channel}/{msg_id}" if channel and msg_id else TG_CHANNEL_LINK

    t = f"{_cp_hc_e(SC_E_HEAD)} <b>SOFTCAP SUCCESSFULLY FILLED</b>\n\n"
    t += f"{body}\n\n"
    t += f"{_cp_hc_e(CP_HDR_SALE_ID)} <b>SALE Details</b>\n"
    t += ("<blockquote>" + _ps_grid(LBL, VAL, [
        ("Min Buy", mnb or "N/A"),
        ("Max Buy", mxb or "N/A"),
        ("Softcap", soft or "N/A"),
        ("Hardcap", hard or "N/A"),
    ]) + "</blockquote>\n\n")
    t += f"{_cp_hc_e(SC_E_HEAD)} <b>TIMELINE:</b>\n"
    t += f"<blockquote>{html.escape(timeline)}</blockquote>\n\n"
    t += (f'{_cp_hc_e(CP_LINK_DETAILS_ID)}<a href="{det_link}">Details</a>  '
          f'{_cp_hc_e(CP_LINK_CHEESEPAD_ID)}<a href="{pool_link}">CheesePad</a>  '
          f'{_cp_hc_e(CP_LINK_KOL_ID)}<a href="{ch_link}">KOL</a>')
    return t, [CP_EMOJI["cheesepad"]]


# ── SOFTCAP VIDEO ────────────────────────────────────────────────────────────
#   Base: si_half_hardcap.mp4 jaisa video (embedded, neeche file ke end me). Har post ke liye patch:
#     * title        -> "SOFTCAP FILLED" (SOFTCAP peela, FILLED safed)
#     * $SI          -> project ka symbol
#     * N BNB / %    -> softcap amount + softcap/hardcap % (count-up animation same)
#     * bar          -> softcap/hardcap tak bharta hai
#     * Raised / X   -> hardcap (hardcap na ho to softcap)
#     * participants -> real count (nahi mila to hide)
#     * neela logo   -> caller channel ka profile logo
#   Render: ~120 frames numpy/PIL + 1 ffmpeg encode, nice 10, ek waqt me ek hi render.
#   Output + temp base copy ek hi temp folder (cpsc_*) me; post ke baad poora folder delete.

SCV_P_END   = 0.496          # base video ke end par bar ka fill (~50%)
SCV_BAR_X0  = 140
SCV_BAR_W   = 801
SCV_TITLE_BOX  = (270, 165, 860, 212)      # x0, y0, x1, y1
SCV_TITLE_X0   = 278
SCV_TITLE_X1   = 818                        # base title ("HALF HARDCAP FILLED") ka right edge
SCV_TITLE_BASE = 202                        # title baseline (y)
SCV_TITLE_SIZE = 40
SCV_TITLE_TRACK = 5.67
SCV_TITLE_FADE = 90
SCV_PCT_COLOR  = (227, 186, 53)
SCV_PCT_SIZE   = 30
SCV_EMBED_NAME = "si_softcap_base.mp4"
SCV_FRAMES_MIN = 60


def _scv_base_video(out_dir):
    """Base video ko render ke temp folder me likho (assets me ho to wahi use). None = base nahi mila."""
    for p in (os.environ.get("CP_SC_BASE_VIDEO") or "",
              os.path.join(_HCV_HERE, "assets", SCV_EMBED_NAME),
              os.path.join(_HCV_HERE, SCV_EMBED_NAME),
              os.path.join(os.getcwd(), SCV_EMBED_NAME)):
        if p and os.path.isfile(p):
            return p
    emb = globals().get("_SCV_EMBED_B64")
    if not emb:
        return None
    p = os.path.join(out_dir, "base.mp4")
    with open(p, "wb") as fh:
        fh.write(base64.b64decode(emb))
    return p


def _scv_title_layers(w_new_txts):
    """[(text, color)] -> (mask_yellow, mask_white, width). Har masks band-size ke float arrays."""
    x0, y0, x1, y1 = SCV_TITLE_BOX
    bw, bh = x1 - x0, y1 - y0
    font = _hcv_font("Bold", SCV_TITLE_SIZE)
    layers = []
    for _ in w_new_txts:
        layers.append(Image.new("L", (bw, bh), 0))
    draws = [ImageDraw.Draw(im) for im in layers]
    x = float(SCV_TITLE_X0 - x0)
    for idx, (txt, _col) in enumerate(w_new_txts):
        for ch in txt:
            if ch != " ":
                draws[idx].text((x, SCV_TITLE_BASE - y0), ch, font=font, fill=255, anchor="ls")
            x += font.getlength(ch) + SCV_TITLE_TRACK
    width = x - SCV_TITLE_TRACK - SCV_TITLE_X0
    return [np.asarray(im, dtype=np.float32) / 255.0 for im in layers], width


def _scv_dilate(m, n=2):
    for _ in range(n):
        t = m.copy()
        t[1:, :] |= m[:-1, :]; t[:-1, :] |= m[1:, :]
        t[:, 1:] |= m[:, :-1]; t[:, :-1] |= m[:, 1:]
        m = t
    return m


def _scv_cover(f, x0, y0, x1, y1):
    """Purana text mita do: har row me left/right ke pixel ke beech gradient (card ka glow na bigde)."""
    x0 = max(1, x0)
    x1 = min(x1, HCV_W - 2)
    left = f[y0:y1, x0 - 1:x0, :].astype(np.float32)
    right = f[y0:y1, x1:x1 + 1, :].astype(np.float32)
    t = np.linspace(0.0, 1.0, x1 - x0, dtype=np.float32)[None, :, None]
    f[y0:y1, x0:x1, :] = (left * (1.0 - t) + right * t).astype(np.uint8)


def _scv_patch_frame(f, st):
    """f: (H,W,3) uint8 (in-place). st: dict(sym, soft_num, hard_num, p_target, cur, dec, parts, logo, cache, title)."""
    R = f[:, :, 0].astype(np.int16)
    G = f[:, :, 1].astype(np.int16)
    B = f[:, :, 2].astype(np.int16)

    # 1) right logo (neela disc) -> caller logo
    if st["logo"]:
        sub = (B[:210, 840:1060] > 150) & (R[:210, 840:1060] < 90) & (G[:210, 840:1060] < 120)
        n = int(sub.sum())
        if n > 300:
            ys, xs = np.where(sub)
            x0, x1, y0, y1 = xs.min() + 840, xs.max() + 840, ys.min(), ys.max()
            cx, cy = (x0 + x1) / 2.0, (y0 + y1) / 2.0
            r = max(x1 - x0, y1 - y0) / 2.0 + 1.0
            a = min(1.0, n / 2000.0)
            _hcv_paste_logo(f, st["cache"], st["logo"], cx, cy, r, a)

    # 2) $SYMBOL  (text slide-in ke time left logo ke paas wala hissa bhi pakadte hain)
    rx0, ry0, rx1, ry1 = 244, 62, 860, 152
    TX0 = 281 - rx0
    reg = R[ry0:ry1, rx0:rx1]
    strong = (reg > 110) & (G[ry0:ry1, rx0:rx1] > 85) & (B[ry0:ry1, rx0:rx1] < 90)
    mk = reg > 60
    mk[:, :TX0] = strong[:, :TX0] & (reg[:, :TX0] > 140)
    if mk.sum() > 40:
        ys, xs = np.where(mk)
        dx, dy = int(xs.min() + rx0 - 280), int(ys.min() + ry0 - 80)
        a = min(1.0, float(reg[:, TX0:].max()) / 250.0)
        er = reg > 18                       # halka/fade hota purana text bhi mitao
        er[:, :TX0] = strong[:, :TX0]
        dm = _scv_dilate(er, 3)
        sreg = f[ry0:ry1, rx0:rx1]
        sreg[dm] = (6, 6, 4)
        txt = "$" + st["sym"]
        size = 64
        font = _hcv_font("Bold", size)
        while font.getlength(txt) > 540 and size > 28:
            size -= 2
            font = _hcv_font("Bold", size)
        mask = _hcv_text_layer(rx1 - rx0, ry1 - ry0, txt, font,
                               (280 + dx - rx0, 131 + dy - ry0), "ls")
        _hcv_blend(f, rx0, ry0, mask, HCV_SYM_COLOR, a)

    # 3) title  "HALF HARDCAP FILLED" -> "SOFTCAP FILLED" (reveal animation base ke hisaab se)
    tx0, ty0, tx1, ty1 = SCV_TITLE_BOX
    band = f[ty0:ty1, tx0:tx1]
    lum = band.max(axis=2)
    cols = np.where((lum > 60).any(axis=0))[0]
    if len(cols):
        xmax = int(cols.max()) + tx0
        frac = max(0.0, min(1.0, (xmax - SCV_TITLE_X0) / float(SCV_TITLE_X1 - SCV_TITLE_X0)))
        oldm = _scv_dilate(lum > 14, 2)
        oldm[:, :max(0, SCV_TITLE_X0 - 3 - tx0)] = False      # left logo ka glow na chhuo
        band[oldm] = (0, 0, 0)
        (m_y, m_w), w_new = st["title"]
        if frac >= 0.995:
            ax = np.ones(band.shape[1], dtype=np.float32)
        else:
            ext = SCV_TITLE_X0 + frac * w_new
            xs_abs = np.arange(tx0, tx1, dtype=np.float32)
            ax = np.clip(0.2 + (ext - xs_abs) / float(SCV_TITLE_FADE) * 0.8, 0.0, 1.0)
            ax[xs_abs > ext] = 0.0
        a_y = (m_y * ax[None, :])[..., None]
        a_w = (m_w * ax[None, :])[..., None]
        yc = np.array(HCV_SYM_COLOR, dtype=np.float32)[None, None, :]
        wc = np.array(HCV_WHITE, dtype=np.float32)[None, None, :]
        out = band.astype(np.float32) * (1.0 - a_y - a_w) + yc * a_y + wc * a_w
        band[:] = np.clip(out, 0, 255).astype(np.uint8)

    # 4) card
    col = f[240:462, 300, :].astype(np.int16)
    hit = np.where((col[:, 0] > 170) & (col[:, 1] > 130) & (col[:, 2] < 90))[0]
    if not len(hit):
        return
    ty = int(hit[0]) + 240

    # base bar fill -> p_rel (0..1) -> p_disp (0..p_target)
    brow = f[ty + 76, 148:938, 0].astype(np.int16)
    dark = np.where(brow < 90)[0]
    base_end_x = (148 + int(dark[0])) if len(dark) else (SCV_BAR_X0 + SCV_BAR_W)
    p_base = 1.0 if len(dark) == 0 else float(dark[0]) / 790.0
    p_rel = max(0.0, min(1.0, p_base / SCV_P_END))
    if p_rel > 0.985:
        p_rel = 1.0
    p_disp = p_rel * st["p_target"]

    amt_reg = f[ty + 14:ty + 52, 312:620, :]
    ca = min(1.0, float(amt_reg.min(axis=2).max()) / 230.0)

    # bar (base ka shimmer/gradient strip stretch karke)
    y0b, y1b = ty + 68, ty + 92
    src = f[y0b:y1b, :, :].copy()
    trk = src[:, 900:901, :]
    L_base = base_end_x - SCV_BAR_X0
    L_new = int(round(p_disp * SCV_BAR_W))
    f[y0b:y1b, 148:933, :] = trk
    if L_new >= 16 and L_base >= 16:
        mid_src = src[:, 148:base_end_x - 8, :]
        mid_w = L_new - 16
        if mid_w > 0 and mid_src.shape[1] > 0:
            mid = np.asarray(Image.fromarray(mid_src).resize((mid_w, y1b - y0b), Image.BILINEAR))
            f[y0b:y1b, 148:148 + mid_w, :] = mid
        f[y0b:y1b, SCV_BAR_X0 + L_new - 8:SCV_BAR_X0 + L_new, :] = src[:, base_end_x - 8:base_end_x, :]
    elif L_new > 0:
        f[y0b:y1b, SCV_BAR_X0:SCV_BAR_X0 + L_new, :] = (253, 212, 8)

    # amount "N BNB"
    _scv_cover(f, 312, ty + 14, 620, ty + 52)
    amt = f"{_hcv_fmt_amount(st['soft_num'], p_rel, st['dec'])} {st['cur']}"
    m = _hcv_text_layer(308, 38, amt, _hcv_font("Bold", 36), (319 - 312, 32), "ls")
    _hcv_blend(f, 312, ty + 14, m, HCV_WHITE, ca)

    # percent (right aligned @ x=940)
    pct = int(round((st["p_target"] if p_rel >= 1.0 else p_disp) * 100))
    if p_rel >= 1.0 and st["p_target"] >= 0.995:
        pct = 100
    _scv_cover(f, 850, ty + 14, 946, ty + 52)
    m = _hcv_text_layer(96, 38, f"{pct}%", _hcv_font("Medium", SCV_PCT_SIZE), (940 - 850, 30), "rs")
    _hcv_blend(f, 850, ty + 14, m, SCV_PCT_COLOR, ca)

    # "Raised / X BNB"
    cap_txt = f"{_hcv_fmt_amount(st['cap_num'], 1.0, st['dec'])} {st['cur']}"
    ra = f[ty + 92:ty + 132, 136:470, :]
    rca = min(1.0, float(ra.max()) / 190.0)
    _scv_cover(f, 136, ty + 92, 470, ty + 132)
    m = _hcv_text_layer(334, 40, f"Raised / {cap_txt}", _hcv_font("Medium", 25), (139 - 136, 123 - 92), "ls")
    _hcv_blend(f, 136, ty + 92, m, HCV_TAN_COLOR, rca)

    # participants (right aligned @ x=940)
    _scv_cover(f, 690, ty + 92, 946, ty + 132)
    if st["parts"] is not None:
        n_now = st["parts"] if p_rel >= 1.0 else int(round(st["parts"] * p_rel))
        lbl = "participant" if n_now == 1 else "participants"
        m = _hcv_text_layer(256, 40, f"{n_now} {lbl}", _hcv_font("Medium", 25), (939 - 690, 123 - 92), "rs")
        _hcv_blend(f, 690, ty + 92, m, HCV_TAN_COLOR, rca)


def cp_sc_render_sync(symbol, soft_cap_txt, hard_cap_txt, participants, logo_bytes, currency=None, title_parts=None):
    """Blocking. Returns mp4 path (temp) ya None. Call karne ke baad cp_sc_cleanup(path) zaroor."""
    if not _hcv_setup():
        return None
    soft_num, cur, dec = _hcv_parse_cap(soft_cap_txt, currency or "BNB")
    if not soft_num or soft_num <= 0:
        return None
    hard_num, _c2, dec2 = _hcv_parse_cap(hard_cap_txt, currency or "BNB")
    if currency:
        cur = str(currency).upper()
    if hard_num and hard_num > soft_num:
        cap_num, p_target, dec = hard_num, max(0.02, min(1.0, soft_num / hard_num)), max(dec, dec2)
    else:
        cap_num, p_target = soft_num, 1.0       # hardcap nahi (Fairlaunch) -> bar softcap ke 100% tak
    _hcv_sweep_sc()
    out_dir = tempfile.mkdtemp(prefix="cpsc_")
    out = os.path.join(out_dir, "softcap.mp4")
    dec_p = enc_p = None
    try:
        base_video = _scv_base_video(out_dir)
        if not base_video:
            shutil.rmtree(out_dir, ignore_errors=True)
            return None
        layers, w_new = _scv_title_layers(title_parts or [("SOFTCAP", HCV_SYM_COLOR), (" FILLED", HCV_WHITE)])
        st = {"sym": _hcv_clean_symbol(symbol), "soft_num": soft_num, "cap_num": cap_num, "p_target": p_target,
              "cur": cur, "dec": dec, "parts": (int(participants) if participants is not None else None),
              "logo": logo_bytes, "cache": {}, "title": ((layers[0], layers[1]), w_new)}
        fsz = HCV_W * HCV_H * 3
        with _HCV_LOCK:
            nice = lambda: os.nice(10)
            dec_p = subprocess.Popen(
                [_HCV_FFMPEG, "-v", "error", "-threads", "2", "-i", base_video,
                 "-f", "rawvideo", "-pix_fmt", "rgb24", "-"],
                stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, preexec_fn=nice)
            enc_p = subprocess.Popen(
                [_HCV_FFMPEG, "-v", "error", "-y", "-f", "rawvideo", "-pix_fmt", "rgb24",
                 "-s", f"{HCV_W}x{HCV_H}", "-r", "30", "-i", "-",
                 "-c:v", "libx264", "-preset", "veryfast", "-crf", "23", "-threads", "2",
                 "-pix_fmt", "yuv420p", "-movflags", "+faststart", "-an", out],
                stdin=subprocess.PIPE, stderr=subprocess.DEVNULL, preexec_fn=nice)
            nfr = 0
            while True:
                buf = dec_p.stdout.read(fsz)
                if len(buf) < fsz:
                    break
                fr = np.frombuffer(buf, dtype=np.uint8).reshape(HCV_H, HCV_W, 3).copy()
                _scv_patch_frame(fr, st)
                enc_p.stdin.write(fr.tobytes())
                nfr += 1
            enc_p.stdin.close()
            enc_p.wait(timeout=60)
            dec_p.wait(timeout=10)
        # base video ki temp copy ab nahi chahiye (sirf output rakho)
        try:
            bp = os.path.join(out_dir, "base.mp4")
            if os.path.isfile(bp):
                os.remove(bp)
        except Exception:
            pass
        if nfr < SCV_FRAMES_MIN or not os.path.isfile(out) or os.path.getsize(out) < 5000:
            shutil.rmtree(out_dir, ignore_errors=True)
            return None
        return out
    except Exception as e:
        logger.warning(f"cp_sc render failed: {e}")
        for p_ in (dec_p, enc_p):
            try:
                if p_ and p_.poll() is None:
                    p_.kill()
            except Exception:
                pass
        shutil.rmtree(out_dir, ignore_errors=True)
        return None
    finally:
        try:
            import gc
            gc.collect()
        except Exception:
            pass


def _hcv_sweep_sc(max_age=900):
    """Purani cpsc_* temp dirs (crash/restart se bachi hui) saaf."""
    try:
        now = time.time()
        base = tempfile.gettempdir()
        for n in os.listdir(base):
            if n.startswith("cpsc_"):
                p = os.path.join(base, n)
                if now - os.path.getmtime(p) > max_age:
                    shutil.rmtree(p, ignore_errors=True)
    except Exception:
        pass


def cp_sc_cleanup(path):
    """Post hone ke foran baad: video + uska temp folder delete."""
    try:
        if path and os.path.basename(os.path.dirname(path)).startswith("cpsc_"):
            shutil.rmtree(os.path.dirname(path), ignore_errors=True)
        elif path and os.path.isfile(path):
            os.remove(path)
    except Exception:
        pass


async def cp_sc_make_video(bot, w, snap):
    """Watch-entry + snapshot se softcap video. None = video nahi bana -> text-only post."""
    try:
        d = snap["d"]
        sym = str(d.get("symbol") or d.get("name") or "").strip()
        logo = await _cp_hc_fetch_logo(bot, w.get("channel"))
        return await asyncio.to_thread(
            cp_sc_render_sync, sym, d.get("soft_cap"), d.get("hard_cap"),
            snap.get("participants"), logo, d.get("currency"))
    except Exception as e:
        logger.warning(f"cp_sc video build failed: {e}")
        return None


# ── channel post + caller DM forward ─────────────────────────────────────────

async def _cp_sc_post(bot, w, snap):
    info = dict(w["info"])
    text, emoji_ids = build_cp_softcap_post(
        w.get("channel", ""), w.get("pid"), w.get("msg_id"), info, snap["d"], w)

    vid_path = None
    try:
        vid_path = await cp_sc_make_video(bot, w, snap)
    except Exception as e:
        logger.warning(f"cp_sc video gen failed: {e}")

    sent = None
    sent_id = None
    try:
        if vid_path and userbot_client:
            try:
                sent = await _userbot_send_media_with_emoji(
                    bot, TARGET_CHANNEL, vid_path, "video", text, emoji_ids, forced_pack={})
            except Exception as e:
                logger.warning(f"cp_sc userbot media send failed: {e}")
        if not sent and userbot_client:
            try:
                sent = await _userbot_send_with_premium_emoji(
                    TARGET_CHANNEL, text, emoji_ids, link_preview=False, forced_pack={})
            except Exception as e:
                logger.warning(f"cp_sc userbot text send failed: {e}")
        sent_id = getattr(sent, "id", None)

        if not sent_id:   # bot API fallback (premium emoji nahi)
            plain = _cp_hc_plain(text)
            if vid_path:
                fh = None
                try:
                    fh = open(vid_path, "rb")
                    m = await bot.send_video(TARGET_CHANNEL, video=fh, caption=plain[:1024],
                                             parse_mode="HTML", width=1080, height=462,
                                             duration=4, supports_streaming=True)
                    sent_id = m.message_id
                except Exception as e:
                    logger.warning(f"cp_sc media fallback failed: {e}")
                finally:
                    if fh:
                        fh.close()
            if not sent_id:
                m = await bot.send_message(TARGET_CHANNEL, _cp_hc_plain(text), parse_mode="HTML",
                                           disable_web_page_preview=True)
                sent_id = m.message_id
    finally:
        cp_sc_cleanup(vid_path)            # post hote hi temp video delete -> Railway disk/cache saaf

    logger.info(f"🧀✅ CheesePad SOFTCAP FILLED posted @{w.get('channel')} "
                f"pid={w.get('pid')} msg={sent_id} video={'gen' if vid_path else 'none'}")
    ok = await _ps_forward_to_caller(bot, w.get("channel"), sent_id)
    if not ok:
        logger.info(f"cp_sc: @{w.get('channel')} ka owner linked nahi / DM forward nahi hua")
    return sent_id


async def _cp_sc_finish(bot, w, snap, key):
    try:
        await _cp_sc_post(bot, w, snap)
    except Exception as e:
        logger.error(f"cp_sc post failed {key}: {e}", exc_info=True)
        # fail hua -> posted mark hatao taake agle poll par dobara try ho (max 3 baar)
        cur = [k for k in _cp_sc_posted() if k != key]
        ff = cfg_get("cp_sc_fails", {}) or {}
        ff[key] = int(ff.get(key, 0)) + 1
        cfg_set("cp_sc_fails", ff)
        cfg_set("cp_sc_posted", (cur + ([key] if ff[key] > 3 else []))[-500:])
    finally:
        _CP_SC_INFLIGHT.discard(key)


async def _cp_sc_consider(bot, w, snap, key):
    """cp_hc_check_once se har poll par call hota hai (snapshot pehle se fetch ho chuka hota hai)."""
    try:
        if not key or key in _CP_SC_INFLIGHT or key in set(_cp_sc_posted()):
            return
        d = snap.get("d") or {}
        info = dict(w.get("info") or {})
        if not _cp_sc_applies(d, info) or not _cp_sc_is_filled(d):
            return
        status = str(d.get("status", "")).lower()
        if status in ("ended", "completed", "cancelled", "upcoming"):
            return                                 # sirf live sale par post
        en = w.get("end_ts") or _ps_epoch(d.get("end_time"))
        if en and time.time() > en:
            return
        if _cp_hc_is_filled(d):
            return                                 # hardcap bhi fill -> HARDCAP post alag se jayegi
        _CP_SC_INFLIGHT.add(key)
        cfg_set("cp_sc_posted", (_cp_sc_posted() + [key])[-500:])   # pehle mark -> duplicate nahi
        t_ = asyncio.get_event_loop().create_task(_cp_sc_finish(bot, w, snap, key))
        _CP_SC_TASKS.add(t_)
        t_.add_done_callback(_CP_SC_TASKS.discard)
    except Exception as e:
        logger.warning(f"cp_sc consider failed {key}: {e}")



# ═══════════════════════════════════════════════════════════════════════════
# CHEESEPAD — FAIRLAUNCH ENDED (NO HARDCAP) ALERT + VIDEO  (owner 2026-10-20)
#   Jin projects ki hardcap nahi hoti, un ki Fairlaunch khatam hote hi:
#     1) bot video banata hai (title "FAIRLAUNCH ENDED", symbol, caller logo, raised, participants)
#     2) main channel (TARGET_CHANNEL) pe video + template post (hardcap-filled jaisi details/emojis)
#     3) wohi post caller (linked KOL owner) ke DM me forward
#   Ye hardcap watcher (cp_hc_check_once) ke andar chalta hai: har poll ka snapshot reuse hota hai,
#   CheesePad ki koi extra API call nahi lagti. Har project ke liye sirf ek baar.
#   Sirf bina-hardcap Fairlaunch. Hardcap wale projects par kuch nahi badla.
#   Test:  /testfl                      -> dummy data ka preview (sirf aap ke DM me)
#          /testfl <cheesepad link> @caller -> asli project ke data ka preview (DM only)
# ═══════════════════════════════════════════════════════════════════════════

_CP_FE_INFLIGHT = set()
_CP_FE_TASKS = set()
_CP_FE_CMD_READY = False
CP_FE_FAIL_MAX = 3


def _cp_fe_posted() -> list:
    return list(cfg_get("cp_fe_posted", []) or [])


def _cp_fe_applies(d: dict, info: dict) -> bool:
    """Sirf bina hardcap wali Fairlaunch."""
    try:
        if _ps_num(d.get("hard_cap")):
            return False
        return bool(_cp_is_fairlaunch(d, info))
    except Exception:
        return False


def _cp_fe_is_ended(d: dict, w: dict) -> bool:
    status = str(d.get("status", "")).lower()
    if status in ("cancelled", "canceled", "failed", "upcoming"):
        return False
    if status in ("ended", "completed", "finalized", "success", "successful"):
        return True
    en = (w or {}).get("end_ts") or _ps_epoch(d.get("end_time"))
    return bool(en and time.time() > en)


def _cp_fe_softcap_failed(d: dict) -> bool:
    """Softcap thi aur fill nahi hui -> Fairlaunch fail, 'ended' post nahi bhejni."""
    soft = _ps_num(d.get("soft_cap"))
    raised = _ps_num(d.get("raised")) or 0
    return bool(soft and soft > 0 and raised < soft * SC_FILL_RATIO)


def build_cp_fairlaunch_end_post(channel, pid, msg_id, info, d, participants, w):
    """Hardcap-filled post ka same style/details/emojis; sirf title + body badli. Returns (html_text, emoji_ids)."""
    chain = (info.get("chain") or "").upper()
    kind = "Fairlaunch"
    sw = kind.lower()
    sym = str(d.get("symbol") or d.get("name") or "").strip().lstrip("$")
    sym_h = html.escape(sym) if sym else "TOKEN"
    handle = html.escape(_display_handle(channel))
    cur = d.get("currency") or _ps_native(chain) or "BNB"

    st = (w or {}).get("call_state") or "before_start"
    raised_call = (w or {}).get("raised_at_call") or 0
    if st == "before_start":
        intro = f"@{handle} posted ${sym_h} before the {sw} started."
    elif st == "during_live" and raised_call and raised_call > 0:
        intro = (f"@{handle} posted ${sym_h} when the {sw} was live and "
                 f"{html.escape(_cp_fmt_num(raised_call))} {html.escape(cur)} had been raised.")
    else:
        intro = f"@{handle} posted ${sym_h} after the {sw} went live."

    raised_now = _cp_fmt_num(_ps_num(d.get("raised")))
    raised_part = f" with {html.escape(raised_now)} {html.escape(cur)} raised" if raised_now else ""
    body = f"{intro} The {kind} has now ended{raised_part}. Good luck to everyone who joined."

    HE = _cp_hc_e(CP_HC_E_HEADER)
    DE = _cp_hc_e(CP_HC_E_DETAIL)
    rows = [
        ("Raised:",         f"{html.escape(raised_now)} {html.escape(cur)}" if raised_now else ""),
        (f"{kind} Rate:",   _cp_hc_human(d.get("rate"))),
        ("Listing Rate:",   _cp_hc_human(d.get("listing_rate"))),
        ("Liquidity:",      html.escape(str(d.get("liquidity") or "").strip())),
        ("Participants:",   html.escape(str(participants)) if participants is not None else ""),
        ("LP Locked:",      html.escape(str(d.get("lock_time") or "").strip())),
    ]
    details = "\n".join(f"{DE}<b>{lbl}</b> {val}" for lbl, val in rows if val)   # jo na mile wo line hat jati hai
    ca = html.escape(str(d.get("token") or "").strip())

    det_link = f"{BOT_LINK}?start=cp_{pid}"
    pool_link = cp_pool_link(info)
    ch_link = f"https://t.me/{channel}/{msg_id}" if channel and msg_id else TG_CHANNEL_LINK

    t = f"{HE} <b>{kind.upper()} ENDED</b> {HE}\n\n"
    t += f"{body}\n\n"
    if details:
        t += f"{_cp_hc_e(CP_HC_E_TOKENOMICS)} <b>TOKENOMICS</b>\n"
        t += f"<blockquote>{details}</blockquote>\n\n"
    if ca:
        t += f"{_cp_hc_e(CP_HC_E_CA)} <b>TOKEN CA:</b>\n"
        t += f"<blockquote><code>{ca}</code></blockquote>\n\n"
    t += (f'{_cp_hc_e(CP_LINK_DETAILS_ID)}<a href="{det_link}">Details</a>  '
          f'{_cp_hc_e(CP_LINK_CHEESEPAD_ID)}<a href="{pool_link}">CheesePad</a>  '
          f'{_cp_hc_e(CP_LINK_KOL_ID)}<a href="{ch_link}">KOL</a>')
    return t, [CP_EMOJI["cheesepad"]]


async def cp_fe_make_video(bot, w, snap):
    """Softcap-video machinery reuse: title 'FAIRLAUNCH ENDED', bar full, number = raised. None = text-only post."""
    try:
        d = snap["d"]
        info = w.get("info") or {}
        raised = _ps_num(d.get("raised"))
        if not raised or raised <= 0:
            return None
        cur = d.get("currency") or _ps_native((info.get("chain") or "").upper()) or "BNB"
        sym = str(d.get("symbol") or d.get("name") or "").strip()
        logo = await _cp_hc_fetch_logo(bot, w.get("channel"))
        return await asyncio.to_thread(
            cp_sc_render_sync, sym, f"{_cp_fmt_num(raised)} {cur}", None,
            snap.get("participants"), logo, cur,
            [("FAIRLAUNCH", HCV_SYM_COLOR), (" ENDED", HCV_WHITE)])
    except Exception as e:
        logger.warning(f"cp_fe video build failed: {e}")
        return None


async def _cp_fe_post(bot, w, snap, preview_chat=None):
    """preview_chat set ho to sirf us chat me bhejta hai (channel/forward/posted-mark nahi)."""
    info = dict(w["info"])
    text, emoji_ids = build_cp_fairlaunch_end_post(
        w.get("channel", ""), w.get("pid"), w.get("msg_id"), info,
        snap["d"], snap.get("participants"), w)

    vid_path = None
    try:
        vid_path = await cp_fe_make_video(bot, w, snap)
    except Exception as e:
        logger.warning(f"cp_fe video gen failed: {e}")

    sent = None
    sent_id = None
    try:
        if preview_chat:
            plain = _cp_hc_plain(text)
            if vid_path:
                with open(vid_path, "rb") as fh:
                    cap = plain if len(plain) <= 1024 else None
                    m = await bot.send_video(preview_chat, video=fh, caption=cap, parse_mode="HTML",
                                             width=1080, height=462, duration=4, supports_streaming=True)
                if cap is None:
                    m = await bot.send_message(preview_chat, plain, parse_mode="HTML",
                                               disable_web_page_preview=True)
            else:
                m = await bot.send_message(preview_chat, plain, parse_mode="HTML",
                                           disable_web_page_preview=True)
            return m.message_id

        if vid_path and userbot_client:
            try:
                sent = await _userbot_send_media_with_emoji(
                    bot, TARGET_CHANNEL, vid_path, "video", text, emoji_ids, forced_pack={})
            except Exception as e:
                logger.warning(f"cp_fe userbot media send failed: {e}")
        if not sent and userbot_client:
            try:
                sent = await _userbot_send_with_premium_emoji(
                    TARGET_CHANNEL, text, emoji_ids, link_preview=False, forced_pack={})
            except Exception as e:
                logger.warning(f"cp_fe userbot text send failed: {e}")
        sent_id = getattr(sent, "id", None)

        if not sent_id:   # bot API fallback (premium emoji nahi)
            plain = _cp_hc_plain(text)
            if vid_path:
                fh = None
                try:
                    fh = open(vid_path, "rb")
                    m = await bot.send_video(TARGET_CHANNEL, video=fh, caption=plain[:1024],
                                             parse_mode="HTML", width=1080, height=462,
                                             duration=4, supports_streaming=True)
                    sent_id = m.message_id
                except Exception as e:
                    logger.warning(f"cp_fe media fallback failed: {e}")
                finally:
                    if fh:
                        fh.close()
            if not sent_id:
                m = await bot.send_message(TARGET_CHANNEL, plain, parse_mode="HTML",
                                           disable_web_page_preview=True)
                sent_id = m.message_id
    finally:
        cp_sc_cleanup(vid_path)            # post hote hi temp video + folder delete

    logger.info(f"🧀🏁 CheesePad FAIRLAUNCH ENDED posted @{w.get('channel')} "
                f"pid={w.get('pid')} msg={sent_id} video={'gen' if vid_path else 'none'}")
    ok = await _ps_forward_to_caller(bot, w.get("channel"), sent_id)
    if not ok:
        logger.info(f"cp_fe: @{w.get('channel')} ka owner linked nahi / DM forward nahi hua")
    return sent_id


async def _cp_fe_finish(bot, w, snap, key):
    done = False
    try:
        snap = await _cp_hc_complete(w, snap)       # missing details ke liye <=5 min dobara fetch (hardcap post jaisa)
        await _cp_fe_post(bot, w, snap)
        done = True
    except Exception as e:
        logger.error(f"cp_fe post failed {key}: {e}", exc_info=True)
        ff = cfg_get("cp_fe_fails", {}) or {}
        ff[key] = int(ff.get(key, 0)) + 1
        cfg_set("cp_fe_fails", ff)
        cur = [k for k in _cp_fe_posted() if k != key]       # posted mark hatao -> agle poll par dobara try
        cfg_set("cp_fe_posted", (cur + ([key] if ff[key] > CP_FE_FAIL_MAX else []))[-500:])
        done = ff[key] > CP_FE_FAIL_MAX
    finally:
        _CP_FE_INFLIGHT.discard(key)
        if done:
            _cp_hc_remove(key)                       # watch list se hatao (post ho gayi ya retries khatam)


async def _cp_fe_consider(bot, w, snap, key):
    """cp_hc_check_once se call hota hai. True = post queue/chal rahi hai (watch abhi na hatao)."""
    try:
        if not key:
            return False
        if key in _CP_FE_INFLIGHT:
            return True
        if key in set(_cp_fe_posted()):
            return False
        d = snap.get("d") or {}
        info = dict(w.get("info") or {})
        if not _cp_fe_applies(d, info) or not _cp_fe_is_ended(d, w):
            return False
        raised = _ps_num(d.get("raised"))
        if not raised or raised <= 0:
            return False                             # kisi ne join hi nahi kiya -> post nahi
        if _cp_fe_softcap_failed(d):
            return False                             # softcap fill nahi hui -> fail sale, post nahi
        _CP_FE_INFLIGHT.add(key)
        cfg_set("cp_fe_posted", (_cp_fe_posted() + [key])[-500:])    # pehle mark -> duplicate nahi
        t_ = asyncio.get_event_loop().create_task(_cp_fe_finish(bot, w, snap, key))
        _CP_FE_TASKS.add(t_)
        t_.add_done_callback(_CP_FE_TASKS.discard)
        return True
    except Exception as e:
        logger.warning(f"cp_fe consider failed {key}: {e}")
        return False


# ── TEST ALERT:  /testfl  (owner only, preview sirf DM me) ───────────────────

async def _cp_fe_testcmd(update, context):
    try:
        uid = update.effective_user.id if update.effective_user else 0
        owners = set(globals().get("OWNER_IDS") or []) | set(_lp_owner_ids() or [])
        logger.info(f"/testfl received uid={uid} owner={uid in owners}")
        if uid not in owners:
            return
        msg = update.message
        args = list(context.args or [])
        channel = next((a.lstrip("@") for a in args if a.startswith("@")), "") or "WizardScan"
        link = " ".join(a for a in args if not a.startswith("@"))
        info = detect_launchpad(link) if link else None

        if link and not info:
            await msg.reply_text("Usage: <code>/testfl</code> ya <code>/testfl &lt;cheesepad link&gt; @caller</code>",
                                 parse_mode="HTML")
            return
        if info:
            info["platform"] = "CheesePad"
            await msg.reply_text("⏳ Details fetch ho rahi hain…")
            snap = await asyncio.to_thread(_cp_hc_snapshot, info)
            if not snap:
                await msg.reply_text("❌ Is link ki details nahi mil rahi.")
                return
            d = dict(snap["d"])
            d["hard_cap"] = None                     # preview: bina-hardcap Fairlaunch ki tarah
            if not _ps_num(d.get("raised")):
                d["raised"] = 12.5                   # raised missing ho to sample
            snap = {"raw": snap.get("raw") or {}, "d": d, "participants": snap.get("participants")}
            winfo = {k: info.get(k, "") for k in ("address", "chain", "url", "platform")}
        else:
            await msg.reply_text("⏳ Test Fairlaunch-Ended preview bana raha hoon (dummy data)…")
            winfo = {"address": "0x0000000000000000000000000000000000000000", "chain": "BSC",
                     "url": "", "platform": "CheesePad"}
            d = {"symbol": "TEST", "name": "Test Token", "currency": "BNB", "status": "ended",
                 "raised": 12.5, "soft_cap": None, "hard_cap": None,
                 "rate": "1000000000 TEST", "listing_rate": "800000000 TEST",
                 "liquidity": "60%", "lock_time": "180 days",
                 "token": "0x0000000000000000000000000000000000000000"}
            snap = {"raw": {}, "d": d, "participants": 321}
        w = {"channel": channel, "pid": 0, "msg_id": "", "info": winfo,
             "call_state": "during_live", "raised_at_call": 3.2}
        await _cp_fe_post(context.bot, w, snap, preview_chat=update.effective_chat.id)
    except Exception as e:
        logger.error(f"/testfl failed: {e}", exc_info=True)
        try:
            await update.message.reply_text(f"❌ Test fail: <code>{html.escape(str(e))[:300]}</code>",
                                            parse_mode="HTML")
        except Exception:
            pass


def _cp_fe_boot(context):
    """_lp_ask_boot (har ps_watch_job tick) se: /testfl command ek baar register."""
    global _CP_FE_CMD_READY
    if _CP_FE_CMD_READY:
        return
    try:
        from telegram.ext import CommandHandler
        # group=-5: koi aur group-0 handler (catch-all / commands) is ko shadow na kare
        context.application.add_handler(CommandHandler("testfl", _cp_fe_testcmd), group=-5)
        _CP_FE_CMD_READY = True
        logger.info("cp_fe: /testfl ready")
    except Exception as e:
        logger.warning(f"cp_fe /testfl register failed: {e}")


# ═══════════════════════════════════════════════════════════════════════════
# MISSING DETAILS -> OWNER KO DM  (PinkSale + CheesePad, owner 2026-10-20)
#   Caller pehli bar kisi token ko post kare aur details na milein to:
#     1) bot pehle khud 100% koshish karta hai (LP_ASK_RETRIES baar, har baar sab sources)
#     2) phir bhi missing ho to owner ko DM: kaun kaun si details chahiye
#     3) owner us DM ko REPLY karke details bhejta hai (jaise: softcap 20 / hardcap 40 / min 0.1)
#     4) post ruki rehti hai (bot is dauran bhi har 2 min khud dobara dhundta hai)
#     5) owner reply de ya 1 ghanta guzar jaye -> post ho jati hai
#   Restart par bhi pending asks cfg ("lp_asks") se wapas shuru ho jate hain.
# ═══════════════════════════════════════════════════════════════════════════

LP_OWNER_IDS_DEFAULT = [6018602211]   # owner ka Telegram ID (cfg "lp_ask_owner_ids" se override ho sakta hai)
LP_ASK_RETRIES   = 4          # khud dhoondne ki koshish (pehli fetch ke baad)
LP_ASK_RETRY_GAP = 20         # har koshish ke beech seconds
LP_ASK_WAIT_S    = 3600       # owner ke reply ka intezar (1 ghanta)
LP_ASK_RECHECK_S = 120        # intezar ke dauran bot har itni dair baad khud dobara dhundta hai

_LP_ASKS = {}                 # ask_id -> live state (event, dm list, ...)
_LP_ASK_TASKS = set()
_LP_ASK_READY = False         # reply handler register ho gaya?

_LP_FIELD_LABEL = {
    "symbol": "Token Symbol", "soft_cap": "Soft Cap", "hard_cap": "Hard Cap",
    "min_buy": "Min Buy", "max_buy": "Max Buy", "start_time": "Start Time", "end_time": "End Time",
}
_LP_FIELD_EXAMPLE = {
    "symbol": "symbol ABC", "soft_cap": "softcap 20", "hard_cap": "hardcap 40",
    "min_buy": "min 0.1", "max_buy": "max 2",
    "start_time": "start 21 Oct 2026 14:00", "end_time": "end 22 Oct 2026 14:00",
}
_LP_ALIASES = {
    "symbol": ("symbol", "token", "ticker", "name", "sym"),
    "soft_cap": ("softcap", "soft cap", "soft", "sc"),
    "hard_cap": ("hardcap", "hard cap", "hard", "hc"),
    "min_buy": ("min", "minbuy", "min buy", "minimum"),
    "max_buy": ("max", "maxbuy", "max buy", "maximum"),
    "start_time": ("start", "starts", "start time", "starttime"),
    "end_time": ("end", "ends", "end time", "endtime"),
}
_LP_NONE_WORDS = {"none", "no", "n/a", "na", "nil", "-", "nahi", "nhi", "0"}
_LP_NONE_LABEL = {"soft_cap": "No Soft Cap", "hard_cap": "No Hard Cap", "min_buy": "No Min", "max_buy": "No Max"}


def _lp_na(details, key, label):
    """Owner ne 'none' bola ho to 'No Min' jaisa label, warna 'N/A'."""
    try:
        if key in (details.get("_none") or []):
            return label
    except Exception:
        pass
    return "N/A"


def _lp_owner_ids():
    ids = []

    def add(x):
        try:
            if isinstance(x, bool):
                return
            if isinstance(x, int):
                ids.append(int(x))
            elif isinstance(x, str) and x.strip().lstrip("-").isdigit():
                ids.append(int(x.strip()))
            elif isinstance(x, (list, tuple, set, frozenset)):
                for y in x:
                    add(y)
        except Exception:
            pass
    add(cfg_get("lp_ask_owner_ids", []) or [])
    if not ids:
        add(LP_OWNER_IDS_DEFAULT)
    out = []
    for i in ids:
        if i not in out:
            out.append(i)
    return out


def _lp_missing_fields(info, d):
    """Jo cheezein post me 'N/A' ban kar dikhengi (aur jo owner ne pehle se na di hon)."""
    chain = (info.get("chain") or "").upper()
    miss = []
    if not (str(d.get("symbol") or "").strip() or str(d.get("name") or "").strip()):
        miss.append("symbol")
    if not d.get("currency"):          # API se confirmed data nahi -> caps/limits bhi check karo
        if not (_ps_amount(d.get("soft_cap"), chain) or _ps_amount(d.get("hard_cap"), chain)):
            miss += ["soft_cap", "hard_cap"]
        if not (_ps_amount(d.get("min_buy"), chain) or _ps_amount(d.get("max_buy"), chain)):
            miss += ["min_buy", "max_buy"]
    if not (_ps_time(d.get("start_time")) or _ps_time(d.get("end_time"))):
        miss += ["start_time", "end_time"]
    done = set(d.get("_owner") or [])
    return [m for m in miss if m not in done]


def _lp_merge(dst, src):
    done = set(dst.get("_owner") or [])
    for k, v in (src or {}).items():
        if k in done or str(k).startswith("_"):
            continue
        if v in (None, "", 0, [], {}):
            continue
        dst[k] = v


async def _lp_refetch(platform, info, post_text, details):
    new = await asyncio.to_thread(fetch_launchpad_details_sync, info, post_text)
    _lp_merge(details, new)
    if platform == "CheesePad":
        try:
            snap = await asyncio.to_thread(_cp_hc_snapshot, info)
            if snap and snap.get("d"):
                _lp_merge(details, snap["d"])
        except Exception:
            pass


def _lp_parse_when(s):
    t = str(s or "").strip()
    t = re.sub(r"\b(utc|gmt)\b", "", t, flags=re.I).strip()
    for fmt in ("%Y-%m-%d %H:%M", "%d %b %Y %H:%M", "%d %B %Y %H:%M", "%d-%m-%Y %H:%M",
                "%d/%m/%Y %H:%M", "%b %d %Y %H:%M", "%b %d, %Y %H:%M", "%Y-%m-%d", "%d %b %Y"):
        try:
            import calendar as _cal
            return int(_cal.timegm(datetime.strptime(t, fmt).utctimetuple()))
        except Exception:
            continue
    return None


def _lp_ask_parse(text):
    """Owner ka reply -> {'_post_now': True} | {field: value|None(none)} | {} (samajh nahi aaya)."""
    t = (text or "").strip()
    if t.lower() in ("post", "skip", "ok", "done", "post kar do", "ab post"):
        return {"_post_now": True}
    amap = {}
    for fld, al in _LP_ALIASES.items():
        for a in al:
            amap[a] = fld
    out = {}
    for line in re.split(r"[\n;]+", t):
        line = line.strip()
        if not line:
            continue
        toks = [x for x in re.split(r"[\s:=]+", line) if x]
        fld, used = None, 0
        for n in (2, 1):
            if len(toks) >= n and " ".join(toks[:n]).lower() in amap:
                fld, used = amap[" ".join(toks[:n]).lower()], n
                break
        if not fld:
            continue
        mm = re.match(r"^\s*" + r"[\s:=]+".join(re.escape(x) for x in toks[:used]) + r"[\s:=]*(.*)$", line, re.I)
        val = (mm.group(1) if mm else " ".join(toks[used:])).strip()
        if not val:
            continue
        if val.lower() in _LP_NONE_WORDS:
            out[fld] = None
        elif fld == "symbol":
            sym = re.sub(r"[^A-Za-z0-9._-]", "", val.lstrip("$"))[:14].upper()
            if sym:
                out[fld] = sym
        elif fld in ("start_time", "end_time"):
            out[fld] = _lp_parse_when(val) or val[:40]
        elif re.search(r"\d", val):
            out[fld] = val[:30]
    return out


def _lp_ask_apply(details, parsed):
    owner = list(details.get("_owner") or [])
    none = list(details.get("_none") or [])
    for k, v in parsed.items():
        if k.startswith("_"):
            continue
        owner.append(k)
        if v is None:
            if k not in none:
                none.append(k)
        else:
            details[k] = v
            if k == "symbol" and not details.get("name"):
                details["name"] = v
    details["_owner"] = owner
    details["_none"] = none


def _lp_spawn(coro):
    t = asyncio.get_event_loop().create_task(coro)
    _LP_ASK_TASKS.add(t)
    t.add_done_callback(_LP_ASK_TASKS.discard)
    return t


def _lp_json_safe(d):
    try:
        return json.loads(json.dumps(d, default=str))
    except Exception:
        return {}


def _lp_ask_text(platform, channel, info, details, missing):
    handle = html.escape(_display_handle(channel))
    nm = html.escape(str(details.get("symbol") or details.get("name") or "").strip()) or "naam nahi mila"
    url = html.escape(str(info.get("url") or ""), quote=True)
    lines = "\n".join(f"• {_LP_FIELD_LABEL[m]}" for m in missing)
    ex = "\n".join(_LP_FIELD_EXAMPLE[m] for m in missing)
    mins = LP_ASK_WAIT_S // 60
    return (f"⚠️ <b>{platform} token ki details nahi mili</b>\n\n"
            f"Caller: @{handle}\nToken: {nm}\n🔗 {url}\n\n"
            f"Bot ne {LP_ASK_RETRIES + 1} baar khud dhoondne ki koshish ki, lekin ye details nahi mili:\n{lines}\n\n"
            f"Is message ko <b>REPLY</b> karke details bhejo, aise (sirf missing wali lines):\n<code>{ex}</code>\n\n"
            f"Jo cheez sale mein hai hi nahi uske aage <code>none</code> likho (jaise <code>hardcap none</code>). "
            f"Abhi jaisi hai waisi post karwani ho to sirf <code>post</code> likho.\n"
            f"⏳ {mins} minute tak reply na aaya to bot khud post kar dega.")


async def _lp_ask_open(bot, platform, channel, msg_id, info, post_text, details, missing, resume=None):
    if not _LP_ASK_READY or not cfg_get("lp_ask_enabled", True):
        return None
    if resume:
        ask = {"id": resume["id"], "dm": [tuple(x) for x in resume.get("dm", [])], "created": resume["created"],
               "missing": list(resume.get("missing", missing)), "event": asyncio.Event(), "reply": None, "why": "timeout"}
        _LP_ASKS[ask["id"]] = ask
        return ask
    owners = _lp_owner_ids()
    if not owners:
        logger.warning("lp_ask: owner id nahi mila — direct post")
        return None
    text = _lp_ask_text(platform, channel, info, details, missing)
    dm = []
    for oid in owners:
        try:
            m = await bot.send_message(int(oid), text, parse_mode="HTML", disable_web_page_preview=True)
            dm.append((int(oid), int(m.message_id)))
        except Exception as e:
            logger.warning(f"lp_ask DM failed {oid}: {e}")
    if not dm:
        return None
    aid = f"{platform}|{(info.get('address') or info.get('url') or '').lower()}"
    ask = {"id": aid, "dm": dm, "created": time.time(), "missing": list(missing),
           "event": asyncio.Event(), "reply": None, "why": "timeout"}
    _LP_ASKS[aid] = ask
    rec = {"id": aid, "platform": platform, "channel": channel, "msg_id": str(msg_id or ""),
           "info": {k: info.get(k, "") for k in ("address", "chain", "url", "platform", "sale_type_hint")},
           "post_text": (post_text or "")[:3000], "details": _lp_json_safe(details),
           "missing": list(missing), "dm": [list(x) for x in dm], "created": ask["created"]}
    cur = cfg_get("lp_asks", {}) or {}
    cur[aid] = rec
    cfg_set("lp_asks", cur)
    logger.info(f"lp_ask: owner ko DM gaya {platform} @{channel} missing={missing}")
    return ask


async def _lp_notify(bot, ask, text):
    for cid, _m in (ask or {}).get("dm", []):
        try:
            await bot.send_message(int(cid), text, parse_mode="HTML")
        except Exception:
            pass


async def _lp_post_now(bot, platform, channel, msg_id, info, post_text, details):
    if platform == "PinkSale":
        return await send_pinksale_alert(bot, channel, msg_id, info, post_text, force=True, prefetched=details)
    return await send_cheesepad_alert(bot, channel, msg_id, info, post_text, force=True, prefetched=details)


async def _lp_deferred(bot, platform, channel, msg_id, info, post_text, details, resume=None):
    ask = None
    try:
        miss = _lp_missing_fields(info, details)
        if resume is None:
            for _ in range(LP_ASK_RETRIES):
                if not miss:
                    break
                await asyncio.sleep(LP_ASK_RETRY_GAP)
                try:
                    await _lp_refetch(platform, info, post_text, details)
                except Exception as e:
                    logger.warning(f"lp_ask refetch failed: {e}")
                miss = _lp_missing_fields(info, details)
        if miss:
            ask = await _lp_ask_open(bot, platform, channel, msg_id, info, post_text, details, miss, resume)
        if ask:
            deadline = ask["created"] + LP_ASK_WAIT_S
            while time.time() < deadline:
                try:
                    await asyncio.wait_for(ask["event"].wait(), timeout=min(LP_ASK_RECHECK_S, max(1, deadline - time.time())))
                    break
                except asyncio.TimeoutError:
                    try:
                        await _lp_refetch(platform, info, post_text, details)
                    except Exception:
                        pass
                    if not _lp_missing_fields(info, details):
                        ask["why"] = "auto"
                        break
            if ask["reply"]:
                ask["why"] = "reply"
                _lp_ask_apply(details, ask["reply"])
        await _lp_post_now(bot, platform, channel, msg_id, info, post_text, details)
        if ask:
            msgs = {"reply": "✅ Details mil gayin, post ho gayi.",
                    "auto": "✅ Bot ko details khud mil gayin, post ho gayi.",
                    "timeout": "⏰ Intezar ka waqt khatam, jo details thi unke saath post kar di."}
            await _lp_notify(bot, ask, msgs.get(ask["why"], "✅ Post ho gayi."))
    except asyncio.CancelledError:
        raise
    except Exception as e:
        logger.error(f"lp_deferred failed: {e}", exc_info=True)
        try:
            await _lp_post_now(bot, platform, channel, msg_id, info, post_text, details)
        except Exception:
            pass
    finally:
        if ask:
            _LP_ASKS.pop(ask["id"], None)
            cur = cfg_get("lp_asks", {}) or {}
            if cur.pop(ask["id"], None) is not None:
                cfg_set("lp_asks", cur)


async def _lp_gate(bot, platform, channel, msg_id, info, post_text, details):
    """True = post ruk gayi (background me khud dhoondna + owner se poochna + phir post)."""
    try:
        if not cfg_get("lp_ask_enabled", True):
            return False
        if not _lp_missing_fields(info, details):
            return False
        _lp_spawn(_lp_deferred(bot, platform, channel, msg_id, info, post_text, details))
        return True
    except Exception as e:
        logger.warning(f"lp_gate failed: {e}")
        return False


async def _lp_ask_reply_handler(update, context):
    from telegram.ext import ApplicationHandlerStop
    msg = update.effective_message
    if not msg or not msg.text or not msg.reply_to_message:
        return
    cid, rid = msg.chat_id, msg.reply_to_message.message_id
    ask = None
    for a in list(_LP_ASKS.values()):
        if any(int(c) == int(cid) and int(m) == int(rid) for c, m in a["dm"]):
            ask = a
            break
    if not ask:
        return
    parsed = _lp_ask_parse(msg.text)
    if not parsed:
        ex = "\n".join(_LP_FIELD_EXAMPLE[m] for m in ask["missing"])
        await msg.reply_text("Samajh nahi aaya. Is tarah likho (sirf missing wali lines):\n" + ex +
                             "\nYa sirf <code>post</code> likho.", parse_mode="HTML")
        raise ApplicationHandlerStop
    ask["reply"] = {} if parsed.get("_post_now") else parsed
    ask["event"].set()
    await msg.reply_text("✅ Mil gaya, post bana raha hoon…")
    raise ApplicationHandlerStop


def _lp_ask_boot(context):
    """ps_watch_job se har tick: reply handler ek baar register + restart ke baad pending asks resume."""
    global _LP_ASK_READY
    try:
        _cp_fe_boot(context)              # /testfl (Fairlaunch Ended test) register
    except Exception:
        pass
    try:
        if not _LP_ASK_READY:
            from telegram.ext import MessageHandler, filters
            context.application.add_handler(
                MessageHandler(filters.TEXT & filters.REPLY & filters.ChatType.PRIVATE, _lp_ask_reply_handler),
                group=-5)
            _LP_ASK_READY = True
            logger.info(f"lp_ask: reply handler ready (owners={_lp_owner_ids()})")
    except Exception as e:
        logger.warning(f"lp_ask handler register failed: {e}")
        return
    try:
        pend = cfg_get("lp_asks", {}) or {}
        for aid, rec in list(pend.items()):
            if aid in _LP_ASKS:
                continue
            info = dict(rec.get("info") or {})
            _lp_spawn(_lp_deferred(context.bot, rec.get("platform", "CheesePad"), rec.get("channel", ""),
                                   rec.get("msg_id", ""), info, rec.get("post_text", ""),
                                   dict(rec.get("details") or {}), resume=rec))
    except Exception as e:
        logger.warning(f"lp_ask resume failed: {e}")



